INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l65','set off','',NULL,'/set ɔːf/','He set off down the main street.','他沿着主要街道出发了。','We set off early in the morning.','我们一大早就出发了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l65','hold up the traffic','',NULL,'/hoʊld ʌp ðə ˈtræfɪk/','Jumbo was holding up the traffic.','江伯阻碍了交通。','The accident held up the traffic for hours.','那起事故堵了几个小时的车。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l65','let ... off','',NULL,'/let ɔːf/','We shall let him off this time.','这次我们就饶了他。','The judge let the young man off with a warning.','法官只是警告一下就放过了那个年轻人。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l65','dress up as','',NULL,'/dres ʌp æz/','He dressed up as Santa Claus.','他打扮成圣诞老人。','The kids dressed up as pirates.','孩子们打扮成海盗。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp1','choice','{"stem":"\"I can''t go to the cinema tonight; I ___ write some letters.\"(表''必须''——现在的义务)","options":["might","must","may","could"],"answer_index":1,"stem_cn":"今晚我不能去看电影,我必须写信。","explanation_cn":"\"必须、一定要\"做某事用 must + 动词原形。✓ I can''t go to the cinema tonight; I must write some letters. ✗ may:表\"也许/可以\";✗ might:表\"可能\";✗ could:表\"能够/可能\",都不表\"必须\"。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp1','choice','{"stem":"\"I missed the train, so I ___ take a taxi.\"(表过去的''不得不''——过去义务)","options":["have to","must","ought","had to"],"answer_index":3,"stem_cn":"我误了火车,所以不得不打车。","explanation_cn":"过去的\"不得不\"用 had to(must 没有过去式)。✓ I missed the train, so I had to take a taxi. ✗ must:没有过去式,不表过去;✗ have to:是现在;✗ ought:形式和意思都不合。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp1','choice','{"stem":"\"Fifteen policemen ___ push very hard to move Jumbo.\"(过去的''不得不''——过去义务)","options":["must","have","had to","must to"],"answer_index":2,"stem_cn":"15个警察不得不使很大劲才把江伯推走。","explanation_cn":"过去的\"不得不\"用 had to。✓ Fifteen policemen had to push very hard. ✗ must:不表过去;✗ must to:形式错;✗ have:意思和形式都不合。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp2','choice','{"stem":"\"He ___ come at 4 o''clock if the plane arrives on time.\"(表''应该''——现在的预期/建议)","options":["will","can","must","should"],"answer_index":3,"stem_cn":"如果飞机准点,他应该4点到。","explanation_cn":"\"应该、理应\"(现在的建议或预期)用 should + 动词原形。✓ He should come at 4 o''clock if the plane arrives on time. ✗ must:表\"必须\";✗ will:表将来;✗ can:表\"能够\"。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp2','choice','{"stem":"\"You ___ ask for permission before leaving the table.\"(表''应该''——责任)","options":["have","must to","ought to","should to"],"answer_index":2,"stem_cn":"离开饭桌前你应该先请求许可。","explanation_cn":"\"应该\"还可用 ought to + 动词原形(注意有 to)。✓ You ought to ask for permission. ✗ must to / should to:这两个词后面不加 to;✗ have:意思和形式都不合。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp3','choice','{"stem":"\"I''m sorry I''m late. I ___ taken a taxi.\"(过去本应做而没做:本该打车)","options":["must have","had to","should","should have"],"answer_index":3,"stem_cn":"抱歉我迟到了,我本应该打车的。","explanation_cn":"过去本该做却没做用 should have + 过去分词。✓ I''m sorry I''m late. I should have taken a taxi. ✗ should:表现在或将来的应该;✗ must have:表\"过去一定…\"的推测;✗ had to:表过去确实做了。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp3','choice','{"stem":"\"He ___ known that the police would never allow this.\"(过去本该做/本该知道)","options":["should","should have","must","ought"],"answer_index":1,"stem_cn":"他本应知道警察绝不会允许这种事。","explanation_cn":"过去本该做/本该知道用 should have + 过去分词。✓ He should have known that the police would never allow this. ✗ should:表现在的应该;✗ must:不表过去本应;✗ ought:缺 to have。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp3','choice','{"stem":"\"The policeman told him he ___ gone along a side street.\"(过去本应做而没做:本该走小路)","options":["must have","ought to","ought to have","should"],"answer_index":2,"stem_cn":"警察告诉他本应该走一条小路。","explanation_cn":"过去本该做而没做也可用 ought to have + 过去分词。✓ He ought to have gone along a side street. ✗ ought to:表现在的应该,不表\"本该做而没做\";✗ should:缺 have;✗ must have:表\"过去一定…\"的推测。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp3','choice','{"stem":"\"She ___ come to see me yesterday, but she forgot.\"(过去本应做而没做)","options":["must have","had to","should","should have"],"answer_index":3,"stem_cn":"她昨天本应来看我,但她忘了。","explanation_cn":"过去本该做而没做用 should have + 过去分词。✓ She should have come to see me yesterday, but she forgot. ✗ should:表现在的应该;✗ must have:表推测;✗ had to:表过去确实做了。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp4','choice','{"stem":"\"As he has a good record, we shall ___ this time.\"(短语动词:''饶恕、放过''他)","options":["let him down","let him off","let him out","let him in"],"answer_index":1,"stem_cn":"由于他一贯表现好,这次我们就饶了他。","explanation_cn":"let sb off = 饶恕、放过某人。✓ As he has a good record, we shall let him off this time. ✗ let him down:使他失望;✗ let him in:让他进来;✗ let him out:放他出去。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp4','choice','{"stem":"\"I expected him to help me, but he ___.\"(短语动词:''使我失望'')","options":["let me out","let me off","let me in","let me down"],"answer_index":3,"stem_cn":"我指望他帮我,但他使我失望了。","explanation_cn":"let sb down = 使某人失望。✓ I expected him to help me, but he let me down. ✗ let me off:放过我;✗ let me in:让我进来;✗ let me out:放我出去。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp4','choice','{"stem":"\"If anyone knocks when I''m out, don''t ___.\"(短语动词:''让他进来'')","options":["let him off","let him down","let him in","let him out"],"answer_index":2,"stem_cn":"我不在时如果有人敲门,别让他进来。","explanation_cn":"let sb in = 让某人进来。✓ Don''t let him in. ✗ let him off:放过他;✗ let him down:使他失望;✗ let him out:放他出去。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp5','choice','{"stem":"\"Though Jimmy ___ to go at once, Jumbo refused to move.\"(同意做某事用哪个词)","options":["allowed","admitted","accepted","agreed"],"answer_index":3,"stem_cn":"虽然吉米同意马上走,但江伯拒绝挪动。","explanation_cn":"\"同意做某事\"用 agree to do。✓ Though Jimmy agreed to go at once, Jumbo refused to move. ✗ accepted:accept 后接\"某物\",不接\"to do\";✗ allowed:允许;✗ admitted:承认。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp5','choice','{"stem":"\"We are not allowed to ___ presents from customers.\"(接受某物用哪个词)","options":["agree","admit","accept","agree to"],"answer_index":2,"stem_cn":"不允许我们接受顾客的礼物。","explanation_cn":"\"接受某物\"用 accept sth。✓ We are not allowed to accept presents from customers. ✗ agree:同意,不直接接\"某物\";✗ agree to:后接动作;✗ admit:承认。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp5','choice','{"stem":"\"She ___ to lend me her car.\"(同意做某事)","options":["received","agreed","admitted","accepted"],"answer_index":1,"stem_cn":"她同意把车借给我。","explanation_cn":"\"同意做某事\"用 agree to do。✓ She agreed to lend me her car. ✗ accepted:accept 接\"某物\";✗ received:收到;✗ admitted:承认。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp6','choice','{"stem":"\"Jimmy ___ as Santa Claus.\"(打扮成、装扮成)","options":["dressed","put on","wore","dressed up"],"answer_index":3,"stem_cn":"吉米打扮成圣诞老人。","explanation_cn":"\"(盛装)打扮成\"用 dress up (as)。✓ Jimmy dressed up as Santa Claus. ✗ dressed:一般地\"穿衣\",不含\"装扮成\";✗ put on:后要接衣物;✗ wore:后要接衣物。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp6','choice','{"stem":"\"I got up at 6, washed, and ___ quickly.\"(一般地''穿好衣服'')","options":["dressed","put","wore","dressed up"],"answer_index":0,"stem_cn":"我6点起床,洗漱,很快穿好衣服。","explanation_cn":"一般地\"穿好衣服\"用 dress。✓ I got up at 6, washed, and dressed quickly. ✗ dressed up:含\"盛装装扮\";✗ wore:后要接衣物;✗ put:形式不完整。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',5,'am2_l65_gp6','choice','{"stem":"\"The children ___ as ghosts for the party.\"(为聚会盛装''打扮成'')","options":["put up","dressed","wore up","dressed up"],"answer_index":3,"stem_cn":"孩子们为聚会打扮成鬼的样子。","explanation_cn":"\"打扮成、装扮成\"用 dress up (as)。✓ The children dressed up as ghosts for the party. ✗ dressed:一般穿衣;✗ wore up / put up:搭配错误。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',6,NULL,'choice','{"stem":"美语里\"圣诞老人\"常说:","options":["Old Christmas","Christmas Man","Father Christmas","Santa Claus"],"answer_index":3,"explanation_cn":"美语\"圣诞老人\"常说 Santa Claus;英式说 Father Christmas。✓ dressed up as Santa Claus 打扮成圣诞老人。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',6,NULL,'choice','{"stem":"美语里\"荣誉\"拼作:","options":["honour","onor","honor","honer"],"answer_index":2,"explanation_cn":"美语\"荣誉\"拼作 honor;英式拼作 honour。✓ a guard of honor 仪仗队。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',6,NULL,'choice','{"stem":"circus 的意思是:","options":["马戏团","剧院","动物园","乐队"],"answer_index":0,"explanation_cn":"circus = 马戏团。✓ the circus owner 马戏团老板。\n顺带记:剧院 = theater;动物园 = zoo;乐队 = band."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',6,NULL,'choice','{"stem":"approach 的意思是:","options":["转身","离开","走近,靠近","停下"],"answer_index":2,"explanation_cn":"approach = 走近、靠近。✓ A policeman approached Jimmy. 一个警察走近吉米。\n顺带记:离开 = leave;停下 = stop;转身 = turn around."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',6,NULL,'choice','{"stem":"weigh 的意思是:","options":["观察","计算钱数","测量长度","重,称…的重量"],"answer_index":3,"explanation_cn":"weigh = 重、称…的重量。✓ Jumbo must weigh a few tons. 江伯一定有好几吨重。\n顺带记:测量长度 = measure;计算钱数 = count;观察 = observe."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',6,NULL,'choice','{"stem":"fortunate 的意思是:","options":["著名的","幸运的","富有的","勇敢的"],"answer_index":1,"explanation_cn":"fortunate = 幸运的。✓ it was fortunate that we didn''t have to carry him 值得庆幸的是不必抬它。\n顺带记:富有的 = rich;勇敢的 = brave;著名的 = famous."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',7,NULL,'cloze','{"stem":"第 1 空","context":"Jimmy ___1___ have known that the police would never allow this. A policeman told him he ___2___ have gone along a side street. Fifteen policemen ___3___ push very hard to move Jumbo. As he has a good record, we shall ___4___ this time.","blank_no":1,"options":["should","must","will","can"],"answer_index":0,"explanation_cn":"过去本该做/本该知道用 should have + 过去分词,此处填 should。✓ Jimmy should have known that the police would never allow this.\n✗ must:表推测;✗ will:表将来;✗ can:表能够。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',7,NULL,'cloze','{"stem":"第 2 空","context":"Jimmy ___1___ have known that the police would never allow this. A policeman told him he ___2___ have gone along a side street. Fifteen policemen ___3___ push very hard to move Jumbo. As he has a good record, we shall ___4___ this time.","blank_no":2,"options":["ought to","should to","must to","will"],"answer_index":0,"explanation_cn":"过去本该做而没做也可用 ought to have + 过去分词,此处填 ought to。✓ he ought to have gone along a side street.\n✗ should to:should 后不加 to;✗ must to:must 后不加 to;✗ will:表将来。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',7,NULL,'cloze','{"stem":"第 3 空","context":"Jimmy ___1___ have known that the police would never allow this. A policeman told him he ___2___ have gone along a side street. Fifteen policemen ___3___ push very hard to move Jumbo. As he has a good record, we shall ___4___ this time.","blank_no":3,"options":["had to","must","have to","must to"],"answer_index":0,"explanation_cn":"过去的\"不得不\"用 had to。✓ Fifteen policemen had to push very hard.\n✗ must:不表过去;✗ have to:是现在;✗ must to:形式错。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',7,NULL,'cloze','{"stem":"第 4 空","context":"Jimmy ___1___ have known that the police would never allow this. A policeman told him he ___2___ have gone along a side street. Fifteen policemen ___3___ push very hard to move Jumbo. As he has a good record, we shall ___4___ this time.","blank_no":4,"options":["let him off","let him down","let him in","let him out"],"answer_index":0,"explanation_cn":"let sb off = 饶恕、放过。✓ As he has a good record, we shall let him off this time.\n✗ let him down:使他失望;✗ let him in:让他进来;✗ let him out:放他出去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',8,NULL,'choice','{"stem":"What did the circus owner Jimmy Gates decide to do last Christmas?","options":["Take some presents to a children''s hospital, dressed up as Santa Claus riding a baby elephant","Arrest a policeman","Sell his elephant Jumbo","Open a new circus"],"answer_index":0,"explanation_cn":"课文说 Jimmy decided to take some presents to a children''s hospital, dressed up as Santa Claus, riding a baby elephant called Jumbo。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',8,NULL,'choice','{"stem":"Why did the police have to push Jumbo off the main street?","options":["Jumbo had attacked the crowd","Jumbo was ill","Jumbo was holding up the traffic and refused to move","Jumbo had escaped from the zoo"],"answer_index":2,"explanation_cn":"课文说 Jumbo was holding up the traffic… Jumbo refused to move, so fifteen policemen had to push him off。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',8,NULL,'choice','{"stem":"Why did the police let Jimmy off this time?","options":["Because it was Christmas Day","Because Jumbo has a good record","Because they were afraid of Jumbo","Because Jimmy paid a large fine"],"answer_index":1,"explanation_cn":"课文说 as he has a good record, we shall let him off this time。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',9,NULL,'choice','{"stem":"你想说\"我本应该打车的(可我没打)\"(过去本应做而没做):","options":["I should take a taxi.","I had to take a taxi.","I must have taken a taxi.","I should have taken a taxi."],"answer_index":3,"explanation_cn":"过去本该做却没做用 should have + 过去分词。✓ I should have taken a taxi. 场合:懊悔过去没做某事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',9,NULL,'choice','{"stem":"你想说\"他同意马上就走\"(同意做某事用 agree to do):","options":["He agreed going at once.","He agreed to go at once.","He accepted to go at once.","He agreed go at once."],"answer_index":1,"explanation_cn":"\"同意做某事\"用 agree to do。✓ He agreed to go at once. 场合:表示答应去做一件事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',9,NULL,'choice','{"stem":"你想说\"由于他表现好,这次我们放过他\"(饶恕、放过某人用 let sb off):","options":["As he has a good record, we will let him off this time.","As he has a good record, we will let him out this time.","As he has a good record, we will let him down this time.","As he has a good record, we will let off him this time."],"answer_index":0,"explanation_cn":"\"饶恕、放过某人\"用 let sb off。✓ we will let him off this time. 场合:因表现好而放某人一马。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',10,NULL,'choice','{"stem":"circus 的意思是:","options":["剧院","马戏团","乐队","动物园"],"answer_index":1,"explanation_cn":"circus = 马戏团。✓ the circus owner 马戏团老板。\n顺带记:剧院 = theater;动物园 = zoo;乐队 = band."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',10,NULL,'choice','{"stem":"fortunate 的意思是:","options":["幸运的","勇敢的","富有的","著名的"],"answer_index":0,"explanation_cn":"fortunate = 幸运的。✓ it was fortunate 值得庆幸的。\n顺带记:富有的 = rich;勇敢的 = brave;著名的 = famous."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',10,NULL,'choice','{"stem":"\"He ___ have known that the police would never allow this.\"(过去本该做/本该知道)","options":["must","should","will","can"],"answer_index":1,"stem_cn":"他本应知道警察绝不会允许这种事。","explanation_cn":"过去本该做/本该知道用 should have + 过去分词,此处填 should。✓ He should have known that the police would never allow this.\n✗ must:表推测;✗ will:表将来;✗ can:表能够。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',10,NULL,'choice','{"stem":"\"I missed the train, so I ___ take a taxi.\"(过去不得不)","options":["had to","have to","must","ought"],"answer_index":0,"stem_cn":"我误了火车,所以不得不打车。","explanation_cn":"过去的\"不得不\"用 had to。✓ I missed the train, so I had to take a taxi.\n✗ must:不表过去;✗ have to:是现在;✗ ought:形式和意思都不合。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',10,NULL,'choice','{"stem":"\"should have + 过去分词\" 表示的意思是:","options":["现在正在做","过去本应该做却没做","将来会做","过去一定做了"],"answer_index":1,"explanation_cn":"should have + 过去分词表示过去本该做某事却没有做(常含懊悔、责备)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',10,NULL,'choice','{"stem":"\"let sb off\" 的意思是:","options":["让某人进来","使某人失望","饶恕,放过某人","送某人出去"],"answer_index":2,"explanation_cn":"let sb off = 饶恕、放过某人(不予处罚)。✓ we shall let him off this time 这次我们就饶了他。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',10,NULL,'choice','{"stem":"Why did a policeman say Jimmy ought to have gone along a side street?","options":["Because Santa always uses side streets","Because the hospital was on a side street","Because side streets were prettier","Because Jumbo was holding up the traffic on the main street"],"answer_index":3,"passage":"Last Christmas, the circus owner, Jimmy Gates, decided to take some presents to a children''s hospital. Dressed up as Santa Claus and accompanied by a ''guard of honor'' of six pretty girls, he set off down the main street of the city riding a baby elephant called Jumbo. He should have known that the police would never allow this sort of thing. A policeman approached Jimmy and told him he ought to have gone along a side street as Jumbo was holding up the traffic. Though Jimmy agreed to go at once, Jumbo refused to move. Fifteen policemen had to push very hard to get him off the main street. The police had a difficult time, but they were most amused. ''Jumbo must weigh a few tons,'' said a policeman afterwards, ''so it was fortunate that we didn''t have to carry him. Of course, we should arrest him, but as he has a good record, we shall let him off this time.''","explanation_cn":"课文说 he ought to have gone along a side street as Jumbo was holding up the traffic。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',10,NULL,'choice','{"stem":"How did the police feel, and what did they finally decide?","options":["They were amused and let Jimmy off because Jumbo had a good record","They fined Jimmy a lot of money","They were frightened and ran away","They were angry and arrested Jimmy"],"answer_index":0,"passage":"Last Christmas, the circus owner, Jimmy Gates, decided to take some presents to a children''s hospital. Dressed up as Santa Claus and accompanied by a ''guard of honor'' of six pretty girls, he set off down the main street of the city riding a baby elephant called Jumbo. He should have known that the police would never allow this sort of thing. A policeman approached Jimmy and told him he ought to have gone along a side street as Jumbo was holding up the traffic. Though Jimmy agreed to go at once, Jumbo refused to move. Fifteen policemen had to push very hard to get him off the main street. The police had a difficult time, but they were most amused. ''Jumbo must weigh a few tons,'' said a policeman afterwards, ''so it was fortunate that we didn''t have to carry him. Of course, we should arrest him, but as he has a good record, we shall let him off this time.''","explanation_cn":"课文说 the police had a difficult time, but they were most amused… as he has a good record, we shall let him off。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',10,NULL,'choice','{"stem":"What was Jimmy riding down the main street?","options":["A circus car","A white horse","A bicycle","A baby elephant called Jumbo"],"answer_index":3,"audio":"Last Christmas, the circus owner, Jimmy Gates, decided to take some presents to a children''s hospital. Dressed up as Santa Claus and accompanied by a ''guard of honor'' of six pretty girls, he set off down the main street of the city riding a baby elephant called Jumbo. He should have known that the police would never allow this sort of thing. A policeman approached Jimmy and told him he ought to have gone along a side street as Jumbo was holding up the traffic. Though Jimmy agreed to go at once, Jumbo refused to move. Fifteen policemen had to push very hard to get him off the main street. The police had a difficult time, but they were most amused. ''Jumbo must weigh a few tons,'' said a policeman afterwards, ''so it was fortunate that we didn''t have to carry him. Of course, we should arrest him, but as he has a good record, we shall let him off this time.''","explanation_cn":"课文说 he set off down the main street riding a baby elephant called Jumbo。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l65',10,NULL,'choice','{"stem":"Why did the policeman say it was fortunate they didn''t have to carry Jumbo?","options":["Because they were very tired","Because Jumbo must weigh a few tons","Because Jumbo was asleep","Because it was raining"],"answer_index":1,"audio":"Last Christmas, the circus owner, Jimmy Gates, decided to take some presents to a children''s hospital. Dressed up as Santa Claus and accompanied by a ''guard of honor'' of six pretty girls, he set off down the main street of the city riding a baby elephant called Jumbo. He should have known that the police would never allow this sort of thing. A policeman approached Jimmy and told him he ought to have gone along a side street as Jumbo was holding up the traffic. Though Jimmy agreed to go at once, Jumbo refused to move. Fifteen policemen had to push very hard to get him off the main street. The police had a difficult time, but they were most amused. ''Jumbo must weigh a few tons,'' said a policeman afterwards, ''so it was fortunate that we didn''t have to carry him. Of course, we should arrest him, but as he has a good record, we shall let him off this time.''","explanation_cn":"课文说 ''Jumbo must weigh a few tons,'' said a policeman, ''so it was fortunate that we didn''t have to carry him.''"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l66',2,9,66,'Sweet as honey!','像蜜一样甜!','KS18+KS42 使役结构 have sth done(请/让别人做某事:have + 物 + 过去分词;had the plane packaged / have my car washed / have the plane restored)(教材 L66 Key structures)主考;SD 集合名词主谓一致——美语里 team/group/audience/crew 等作整体用单数(is/was/has)(辅考,美语规则,不出英式复数陷阱)','1963年,一架老式飞机坠落在南太平洋一个偏僻的小岛上,远离任何地方。飞机损坏不严重,但多年后被人遗忘,残骸静静躺着无人问津。后来在1989年,一次对小岛的航拍勘测中它被重新发现了。那时,一架状态这么好的飞机已经很稀有,值得抢救。法国当局请人把飞机打包,分件运回了法国。如今一群爱好者打算请人把飞机修复。它有四个引擎,但这群人只需请人修复其中三个。想象一下他们打开包装箱时有多惊讶——第四个引擎“像蜜一样甜”,依然完好无损。一群蜜蜂把这个引擎变成了蜂房,它被蜂蜡完完全全地封存了起来!','{"q":"Listen and answer — What was ''sweet as honey'' and why?","options":["The fourth engine — a colony of bees had turned it into a hive and preserved it in beeswax","A jar of real honey found on the plane","The island''s wild fruit","The pilot''s old lunch box"],"answer_index":0}'::jsonb,'{"title":"使役结构 have sth done","intro":"KS18+KS42 have + 物 + 过去分词 = 请/让别人做某事(自己不亲自做,而是请人代劳,或遭遇某事)。对比:I washed my car(自己洗)vs I had my car washed(请人洗)。常见生活场景:have my hair cut(理发)、have my watch repaired(修表)、have the plane restored(请人修复飞机)。否定/疑问借助 do:Did you have it repaired? / I didn''t have it repaired。","table":{"headers":["自己做","请别人做(have sth done)"],"rows":[["I washed my car.","I had my car washed."],["I''ll clean my suit.","I''ll have my suit cleaned."],["He cut his hair? (自己)","He had his hair cut."],["They restored the plane.","They had the plane restored."]]},"specialRules":[{"rule":"否定与疑问用 do/did 助动:Did you have your watch repaired? / I didn''t have my watch repaired。各种时态皆可:will have to have it repaired、are going to have it restored、need to have it rebuilt。","mark":"have sth done 时态"},{"rule":"📌 美语规则:team/group/audience/crew/government/staff 等集合名词通常当作一个整体、用单数动词(is/was/has);英式英语有时用复数(are/were),但本美语课程一律以单数为准。","mark":"集合名词用美语单数"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l66',1,NULL,'In 1963, an old airplane came down on a remote island in the South Pacific, a long way from anywhere. The plane wasn''t badly damaged, but over the years it was forgotten, and the wreck lay undisturbed.','1963年,一架老式飞机坠落在南太平洋一个偏僻的小岛上,远离任何地方。飞机损坏不严重,但多年后被人遗忘,残骸静静躺着无人问津。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l66',2,NULL,'Then in 1989, it was rediscovered during an aerial survey of the island. By then, a plane in such condition was rare and worth rescuing.','后来在1989年,一次对小岛的航拍勘测中它被重新发现了。那时,一架状态这么好的飞机已经很稀有,值得抢救。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l66',3,NULL,'The French authorities had the plane packaged and moved back to France in parts. Now a group of enthusiasts is going to have the plane restored.','法国当局请人把飞机打包,分件运回了法国。如今一群爱好者打算请人把飞机修复。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l66',4,NULL,'It has four engines, but the group only needs to have three of them rebuilt. Imagine their surprise when they broke open the packing cases!','它有四个引擎,但这群人只需请人修复其中三个。想象一下他们打开包装箱时有多惊讶!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l66',5,NULL,'The fourth engine was sweet as honey — still in perfect condition. A colony of bees had turned the engine into a hive, and it was completely preserved in beeswax!','第四个引擎“像蜜一样甜”——依然完好无损。一群蜜蜂把这个引擎变成了蜂房,它被蜂蜡完完全全地封存了起来!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
