INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l69','come back to life','',NULL,'/kʌm bæk tə laɪf/','The old car came back to life.','这辆老爷车重获新生。','The town comes back to life in summer.','小镇一到夏天就热闹起来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l69','a great deal of','',NULL,'/ə ɡreɪt diːl əv/','The car needed a great deal of work.','这辆车需要大量修理。','It took a great deal of time.','这花了大量时间。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l69','restore ... to','',NULL,'/rɪˈstɔːr tuː/','It has been restored to its original condition.','它已被修复到原来的状态。','They restored the house to its former glory.','他们把房子修复到往日的辉煌。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l69','work on','',NULL,'/wɜːrk ɑːn/','The team worked on the car for months.','团队修了这辆车好几个月。','She is working on a new project.','她在做一个新项目。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp1','choice','{"stem":"\"This car ___ in Germany in 1925.\"(一般过去被动)","options":["has made","was making","was made","made"],"answer_index":2,"stem_cn":"这辆车1925年在德国制造。","explanation_cn":"一般过去的被动 = was/were + 过去分词。✓ This car was made in Germany in 1925. ✗ made:是主动;✗ was making:过去进行主动;✗ has made:现在完成主动。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp1','choice','{"stem":"\"Only ten of them ___ ever built.\"(一般过去被动,主语复数)","options":["are","were","was","have"],"answer_index":1,"stem_cn":"这种车一共只造过十辆。","explanation_cn":"一般过去被动;主语复数(ten of them)用 were built。✓ Only ten of them were ever built. ✗ was:主语复数不用 was;✗ have:构不成过去被动;✗ are:时态应是过去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp1','choice','{"stem":"\"The maker''s name ___ under the seat.\"(一般过去被动:被发现)","options":["was found","was finding","found","has found"],"answer_index":0,"stem_cn":"制造商的名字在座位下被发现了。","explanation_cn":"一般过去被动:名字\"被发现\"。✓ The maker''s name was found under the seat. ✗ found:主动;✗ was finding:过去进行主动;✗ has found:现在完成主动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp2','choice','{"stem":"\"When it arrived, the engine could hardly ___.\"(情态被动:几乎发动不了)","options":["started","been started","start","be started"],"answer_index":3,"stem_cn":"送来时,引擎几乎发动不了。","explanation_cn":"情态被动 = can/could + be + 过去分词;\"几乎发动不了\"用 could hardly be started。✓ the engine could hardly be started. ✗ start:主动;✗ started:缺 be;✗ been started:缺 be。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp2','choice','{"stem":"\"''It ___,'' said the mechanic.\"(情态被动:它能被修好)","options":["can repair","can be repaired","can repaired","can be repair"],"answer_index":1,"stem_cn":"“它能修好,”技师说。","explanation_cn":"情态被动 = can be + 过去分词。✓ It can be repaired. ✗ can repair:主动;✗ can be repair:缺过去分词;✗ can repaired:缺 be。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp2','choice','{"stem":"\"It ___ in a dry garage — it looks so clean.\"(对过去的推测·被动:一定是被放在…)","options":["must keep","must kept","must be keeping","must have been kept"],"answer_index":3,"stem_cn":"它一定是被放在干燥的车库里——看起来这么干净。","explanation_cn":"对过去的推测(被动)用 must have been + 过去分词。✓ It must have been kept in a dry garage. ✗ must keep:主动且推测现在;✗ must be keeping:进行;✗ must kept:形式错。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp3','choice','{"stem":"\"After months of work, the car ___ fully restored.\"(现在完成被动)","options":["was being","has been","had","is"],"answer_index":1,"stem_cn":"几个月的修理后,这辆车已被完全修复。","explanation_cn":"现在完成的被动 = has been + 过去分词。✓ the car has been fully restored. ✗ was being:过去进行被动;✗ is:构不成完成;✗ had:构不成现在完成被动。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp3','choice','{"stem":"\"The museum ___ several rare cars this year.\"(现在完成主动对照:已收购)","options":["has acquired","acquiring","was acquired","has been acquired"],"answer_index":0,"stem_cn":"博物馆今年已收购了几辆稀有的车。","explanation_cn":"\"博物馆已收购\"是主动的现在完成(museum 主动做);= has + 过去分词。✓ The museum has acquired several rare cars. ✗ has been acquired:那是\"博物馆被收购\",意思反了;✗ was acquired:一般过去被动;✗ acquiring:缺助动词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp3','choice','{"stem":"\"All the broken parts ___ replaced.\"(现在完成被动,主语复数)","options":["was","were being","has been","have been"],"answer_index":3,"stem_cn":"所有坏零件都已被更换。","explanation_cn":"现在完成被动;主语复数(parts)用 have been + 过去分词。✓ All the broken parts have been replaced. ✗ has been:主语复数不用 has;✗ was:一般过去且数不合;✗ were being:过去进行。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp4','choice','{"stem":"\"For years it ___ in an old garage.\"(过去完成被动:一直被存放)","options":["had been kept","kept","was keeping","has kept"],"answer_index":0,"stem_cn":"多年来它一直被存放在一个旧车库里。","explanation_cn":"过去完成的被动 = had been + 过去分词。✓ For years it had been kept in an old garage. ✗ kept:一般过去;✗ was keeping:过去进行主动;✗ has kept:现在完成主动。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp4','choice','{"stem":"\"The car ___ for so long that it needed a lot of work.\"(过去完成被动:被存放)","options":["stored","had been stored","had stored","was storing"],"answer_index":1,"stem_cn":"这辆车被存放了这么久,需要大量修理。","explanation_cn":"过去完成的被动 = had been + 过去分词。✓ The car had been stored for so long. ✗ had stored:主动;✗ was storing:过去进行主动;✗ stored:一般过去。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp5','choice','{"stem":"\"While the car ___ cleaned, the name was found.\"(过去进行被动)","options":["was being","had been","is being","was"],"answer_index":0,"stem_cn":"在清理这辆车时,发现了名字。","explanation_cn":"过去进行的被动 = was being + 过去分词。✓ While the car was being cleaned… ✗ was:缺 being,构不成进行被动;✗ is being:时态应是过去;✗ had been:过去完成被动。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp5','choice','{"stem":"\"When I visited, the engine ___ repaired by two mechanics.\"(过去进行被动)","options":["was","has been","is being","was being"],"answer_index":3,"stem_cn":"我参观时,引擎正被两名技师修理。","explanation_cn":"过去进行被动 = was being + 过去分词。✓ the engine was being repaired by two mechanics. ✗ was:缺 being;✗ is being:时态应是过去;✗ has been:现在完成被动。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp5','choice','{"stem":"\"Every part ___ checked when the manager arrived.\"(过去进行被动)","options":["was","is being","was being","had been"],"answer_index":2,"stem_cn":"经理到时,每个零件正被检查。","explanation_cn":"过去进行被动 = was being + 过去分词。✓ Every part was being checked when the manager arrived. ✗ was:缺 being;✗ is being:时态应是过去;✗ had been:过去完成被动。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp6','choice','{"stem":"\"___ stored for so long, the car needed a great deal of work.\"(完成式非谓语被动,作状语)","options":["Been","Being","Have been","Having been"],"answer_index":3,"stem_cn":"由于被存放了这么久,这辆车需要大量修理。","explanation_cn":"完成式的非谓语被动 = Having been + 过去分词,作状语说明原因/先发生。✓ Having been stored for so long, the car needed a lot of work. ✗ Being:表当前状态,不强调\"已被…\";✗ Have been:非谓语不用原形;✗ Been:缺 having。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp6','choice','{"stem":"\"___ kept in a dry place, the engine was still in good condition.\"(完成式非谓语被动)","options":["Been","Having been","Being","Has been"],"answer_index":1,"stem_cn":"由于被放在干燥处,引擎仍然状况良好。","explanation_cn":"完成式非谓语被动 = Having been + 过去分词。✓ Having been kept in a dry place, the engine was still in good condition. ✗ Being:不强调\"已被…\";✗ Has been:非谓语不用;✗ Been:缺 having。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp6','choice','{"stem":"\"We expected the maker''s name ___ somewhere on the car.\"(不定式被动)","options":["to find","to be find","found","to be found"],"answer_index":3,"stem_cn":"我们估计制造商的名字会印在车上某处。","explanation_cn":"不定式的被动 = to be + 过去分词。✓ We expected the maker''s name to be found somewhere. ✗ to find:主动;✗ to be find:缺过去分词;✗ found:缺 to be。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',5,'am2_l69_gp6','choice','{"stem":"\"The owner wanted the car ___ to its original condition.\"(不定式被动:想让车被修复)","options":["to be restored","to restore","to be restore","restoring"],"answer_index":0,"stem_cn":"车主想让这辆车被修复到原来的状态。","explanation_cn":"不定式的被动 = to be + 过去分词。✓ The owner wanted the car to be restored. ✗ to restore:主动;✗ to be restore:缺过去分词;✗ restoring:不合此结构。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',6,NULL,'choice','{"stem":"美语里\"汽油\"常说:","options":["petrol","gas","oil fuel","car juice"],"answer_index":1,"explanation_cn":"美语\"汽油\"常说 gas(gasoline);英式说 petrol。✓ fill up with gas 加满油。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',6,NULL,'choice','{"stem":"美语里\"轮胎\"拼作:","options":["tire","tyre","tier","tyer"],"answer_index":0,"explanation_cn":"美语\"轮胎\"拼作 tire;英式拼作 tyre。✓ a flat tire 瘪了的轮胎。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',6,NULL,'choice','{"stem":"restore 的意思是:","options":["隐藏","出售","拆毁","修复,复原"],"answer_index":3,"explanation_cn":"restore = 修复、复原。✓ restored to its original condition 修复到原来的状态。\n顺带记:拆毁 = demolish;出售 = sell;隐藏 = hide."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',6,NULL,'choice','{"stem":"rare 的意思是:","options":["稀有的,罕见的","巨大的","普通的","廉价的"],"answer_index":0,"explanation_cn":"rare = 稀有的、罕见的。✓ a rare old car 一辆稀有的老爷车。\n顺带记:普通的 = common;廉价的 = cheap;巨大的 = huge."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',6,NULL,'choice','{"stem":"acquire 的意思是:","options":["丢弃","归还","借出","获得,取得"],"answer_index":3,"explanation_cn":"acquire = 获得、取得。✓ the museum had acquired it 博物馆收购了它。\n顺带记:丢弃 = discard;借出 = lend;归还 = return."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',6,NULL,'choice','{"stem":"original 的意思是:","options":["最后的","最初的,原来的","假的","现代的"],"answer_index":1,"explanation_cn":"original = 最初的、原来的。✓ its original condition 它最初的状态。\n顺带记:最后的 = final;假的 = fake;现代的 = modern."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',7,NULL,'cloze','{"stem":"第 1 空","context":"The car ___1___ in Germany in 1925. For years it ___2___ in an old garage. While it ___3___ cleaned, the maker''s name was found. After months of work, it ___4___ fully restored to its original condition.","blank_no":1,"options":["was made","made","was making","has made"],"answer_index":0,"explanation_cn":"一般过去的被动 = was + 过去分词。✓ The car was made in Germany in 1925.\n✗ made:主动;✗ was making:过去进行主动;✗ has made:现在完成主动。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',7,NULL,'cloze','{"stem":"第 2 空","context":"The car ___1___ in Germany in 1925. For years it ___2___ in an old garage. While it ___3___ cleaned, the maker''s name was found. After months of work, it ___4___ fully restored to its original condition.","blank_no":2,"options":["had been kept","kept","was keeping","has kept"],"answer_index":0,"explanation_cn":"过去完成的被动 = had been + 过去分词。✓ it had been kept in an old garage.\n✗ kept:一般过去;✗ was keeping:过去进行主动;✗ has kept:现在完成主动。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',7,NULL,'cloze','{"stem":"第 3 空","context":"The car ___1___ in Germany in 1925. For years it ___2___ in an old garage. While it ___3___ cleaned, the maker''s name was found. After months of work, it ___4___ fully restored to its original condition.","blank_no":3,"options":["was being","is being","was","had been"],"answer_index":0,"explanation_cn":"过去进行的被动 = was being + 过去分词。✓ While it was being cleaned, the name was found.\n✗ is being:时态应是过去;✗ was:缺 being;✗ had been:过去完成被动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',7,NULL,'cloze','{"stem":"第 4 空","context":"The car ___1___ in Germany in 1925. For years it ___2___ in an old garage. While it ___3___ cleaned, the maker''s name was found. After months of work, it ___4___ fully restored to its original condition.","blank_no":4,"options":["has been","was being","is","had"],"answer_index":0,"explanation_cn":"现在完成的被动 = has been + 过去分词。✓ it has been fully restored.\n✗ was being:过去进行被动;✗ is:构不成完成;✗ had:构不成现在完成被动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',8,NULL,'choice','{"stem":"What kind of car was brought to the museum?","options":["A rare old car made in Germany in 1925, one of only ten ever built","A common family car","A racing car from the 1960s","A brand-new sports car"],"answer_index":0,"explanation_cn":"课文说 a rare old car… was made in Germany in 1925, and only ten of them were ever built。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',8,NULL,'choice','{"stem":"What was found while the car was being cleaned?","options":["A box of money","An old map","The maker''s name, under the seat","The original keys"],"answer_index":2,"explanation_cn":"课文说 While the car was being cleaned, the maker''s name was found under the seat。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',8,NULL,'choice','{"stem":"What condition is the car in now?","options":["It is still broken and unusable","It has been fully restored to its original condition and is admired by visitors","It was scrapped for parts","It was sold to a collector"],"answer_index":1,"explanation_cn":"课文说 the car has been fully restored to its original condition… it is admired by everyone who visits the museum。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',9,NULL,'choice','{"stem":"你想说\"这辆车1925年在德国制造\"(一般过去被动 be + 过去分词):","options":["This car is made in Germany in 1925.","This car was make in Germany in 1925.","This car made in Germany in 1925.","This car was made in Germany in 1925."],"answer_index":3,"explanation_cn":"一般过去的被动 = was + 过去分词。✓ This car was made in Germany in 1925. 场合:说某物是被(在过去)制造的。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',9,NULL,'choice','{"stem":"你想说\"这辆车已被完全修复\"(现在完成被动 has been + 过去分词):","options":["The car has been fully restored.","The car is fully restore.","The car has fully restored.","The car had been fully restoring."],"answer_index":0,"explanation_cn":"现在完成的被动 = has been + 过去分词。✓ The car has been fully restored. 场合:说某事到现在已经被做完。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',9,NULL,'choice','{"stem":"你想说\"清理这辆车时,我们发现了制造商的名字\"(过去进行被动 was being done):","options":["While the car cleaned, we found the maker''s name.","While the car has been cleaned, we found the maker''s name.","While the car was being cleaned, we found the maker''s name.","While the car was cleaning, we found the maker''s name."],"answer_index":2,"explanation_cn":"过去进行的被动 = was being + 过去分词。✓ While the car was being cleaned, we found the maker''s name. 场合:说过去某时某事正在被做。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',10,NULL,'choice','{"stem":"restore 的意思是:","options":["隐藏","修复,复原","出售","拆毁"],"answer_index":1,"explanation_cn":"restore = 修复、复原。✓ restored to its original condition 修复到原来的状态。\n顺带记:拆毁 = demolish;出售 = sell;隐藏 = hide."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',10,NULL,'choice','{"stem":"rare 的意思是:","options":["廉价的","巨大的","普通的","稀有的,罕见的"],"answer_index":3,"explanation_cn":"rare = 稀有的、罕见的。✓ a rare old car 一辆稀有的老爷车。\n顺带记:普通的 = common;廉价的 = cheap;巨大的 = huge."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',10,NULL,'choice','{"stem":"\"This car ___ in Germany in 1925.\"(一般过去被动)","options":["was making","was made","made","has made"],"answer_index":1,"stem_cn":"这辆车1925年在德国制造。","explanation_cn":"一般过去的被动 = was + 过去分词。✓ This car was made in Germany in 1925.\n✗ made:主动;✗ was making:过去进行主动;✗ has made:现在完成主动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',10,NULL,'choice','{"stem":"\"After months of work, the car ___ fully restored.\"(现在完成被动)","options":["has been","had","is","was being"],"answer_index":0,"stem_cn":"几个月后,这辆车已被完全修复。","explanation_cn":"现在完成的被动 = has been + 过去分词。✓ the car has been fully restored.\n✗ was being:过去进行被动;✗ is:构不成完成;✗ had:构不成现在完成被动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',10,NULL,'choice','{"stem":"被动语态的基本结构是:","options":["will + 动词原形","have + 过去分词","be + 过去分词","be + 现在分词"],"answer_index":2,"explanation_cn":"被动语态的基本结构是 be + 过去分词;时态的变化体现在 be 上(was done / has been done / was being done)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',10,NULL,'choice','{"stem":"\"come back to life\" 的意思是:","options":["回到家里","重获新生,恢复活力","醒过来吃饭","突然死去"],"answer_index":1,"explanation_cn":"come back to life = 重获新生、恢复活力(重新变得有生气)。✓ The old car came back to life. 老爷车重获新生。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',10,NULL,'choice','{"stem":"Why did the old car need a great deal of work?","options":["It was too modern to run","It was brand new","It had crashed on the road","It had been stored for years and was in poor condition"],"answer_index":3,"passage":"Last month, a rare old car was brought to our museum, which had recently acquired it. It was made in Germany in 1925, and only ten of them were ever built. For years it had been kept in an old garage and almost forgotten. When it arrived, the engine could hardly be started. ''It can be repaired,'' our chief mechanic said, and he instructed his team to check every part. While the car was being cleaned, the maker''s name was found under the seat. Having been stored for so long, the car needed a great deal of work. Every part was carefully checked, and the broken ones were replaced. With growing confidence, the team worked on, and after months the car has been fully restored to its original condition. Now it is admired by everyone who visits the museum.","explanation_cn":"课文说 it had been kept in an old garage… Having been stored for so long, the car needed a great deal of work。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',10,NULL,'choice','{"stem":"How was the maker''s name discovered?","options":["The former owner told them","It was printed on the door","It was found under the seat while the car was being cleaned","It was in an old newspaper"],"answer_index":2,"passage":"Last month, a rare old car was brought to our museum, which had recently acquired it. It was made in Germany in 1925, and only ten of them were ever built. For years it had been kept in an old garage and almost forgotten. When it arrived, the engine could hardly be started. ''It can be repaired,'' our chief mechanic said, and he instructed his team to check every part. While the car was being cleaned, the maker''s name was found under the seat. Having been stored for so long, the car needed a great deal of work. Every part was carefully checked, and the broken ones were replaced. With growing confidence, the team worked on, and after months the car has been fully restored to its original condition. Now it is admired by everyone who visits the museum.","explanation_cn":"课文说 While the car was being cleaned, the maker''s name was found under the seat。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',10,NULL,'choice','{"stem":"Where had the car been kept for years?","options":["On a race track","In an old garage, almost forgotten","In a showroom","In a museum"],"answer_index":1,"audio":"Last month, a rare old car was brought to our museum, which had recently acquired it. It was made in Germany in 1925, and only ten of them were ever built. For years it had been kept in an old garage and almost forgotten. When it arrived, the engine could hardly be started. ''It can be repaired,'' our chief mechanic said, and he instructed his team to check every part. While the car was being cleaned, the maker''s name was found under the seat. Having been stored for so long, the car needed a great deal of work. Every part was carefully checked, and the broken ones were replaced. With growing confidence, the team worked on, and after months the car has been fully restored to its original condition. Now it is admired by everyone who visits the museum.","explanation_cn":"课文说 For years it had been kept in an old garage and almost forgotten。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l69',10,NULL,'choice','{"stem":"How do visitors feel about the restored car now?","options":["They admire it","They are afraid of it","They ignore it","They dislike it"],"answer_index":0,"audio":"Last month, a rare old car was brought to our museum, which had recently acquired it. It was made in Germany in 1925, and only ten of them were ever built. For years it had been kept in an old garage and almost forgotten. When it arrived, the engine could hardly be started. ''It can be repaired,'' our chief mechanic said, and he instructed his team to check every part. While the car was being cleaned, the maker''s name was found under the seat. Having been stored for so long, the car needed a great deal of work. Every part was carefully checked, and the broken ones were replaced. With growing confidence, the team worked on, and after months the car has been fully restored to its original condition. Now it is admired by everyone who visits the museum.","explanation_cn":"课文说 Now it is admired by everyone who visits the museum。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l70',2,9,70,'What Are You Good At?','你擅长什么?','形容词 + 介词固定搭配(教材 L70 考点,方案B换情节包):形容词+for(famous for/eager for/responsible for/ready for/sorry for)、形容词+of(proud of/afraid of/capable of/fond of/full of)、形容词+at(good at/quick at/surprised at)、形容词+to/with/about/on(grateful to/kind to/pleased with/worried about/keen on)','我们学校因社团众多而出名,人人都渴望在社团里有个名额。米娅画画很擅长,也喜欢画卡通。她哥哥为她感到自豪,可他自己却害怕当众讲话。“你应该负责美术社,”老师说,“你有能力领导它。”米娅对这个提议感到惊讶,也很感激老师。“我有点担心工作量,”她说,“不过我准备好迎接挑战了。”老师对她的回答很满意,对每个加入的人都很友善。很快,美术社就挤满了热爱艺术的学生。米娅为那些没能进来的人感到惋惜,但活动室只能容纳二十个人。到年底时,她因为办了全校最棒的一场画展而出了名。','{"q":"Listen and answer — What is the school famous for?","options":["Its many clubs","Its sports teams","Its old library","Its science labs"],"answer_index":0}'::jsonb,'{"title":"形容词 + 介词固定搭配","intro":"很多形容词后面跟固定的介词,要成组记:①+for——famous for(因…出名)、eager for(渴望)、responsible for(对…负责)、ready for(为…做好准备)、sorry for(为…惋惜);②+of——proud of(为…自豪)、afraid of(害怕)、capable of(有能力)、fond of(喜爱)、full of(充满);③+at——good at(擅长)、quick at(在…上反应快)、surprised at(对…惊讶);④+其他——grateful to(感激)、kind to(对…友善)、pleased with(对…满意)、worried about(担心)、keen on(热衷于)。","table":{"headers":["搭配","例子"],"rows":[["famous for / eager for","Our school is famous for its clubs."],["proud of / afraid of / capable of","He is afraid of speaking in public."],["good at / surprised at","Mia is good at painting."],["grateful to / kind to","Mia was grateful to her teacher."],["pleased with / worried about / keen on","The teacher was pleased with her answer."]]},"specialRules":[{"rule":"美语里“数学”说 math(英式 maths)、“橡皮”说 eraser(英式 rubber)、“成绩”说 grade(英式 mark);本课已按美语写。","mark":"math/eraser/grade"},{"rule":"形容词后的介词是固定的,靠成组记忆:good AT、afraid OF、famous FOR、grateful TO、pleased WITH、worried ABOUT、keen ON。不能随意替换。","mark":"adj + prep"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l70',1,NULL,'Our school is famous for its many clubs, and everyone is eager for a place in one. Mia is really good at painting and fond of drawing cartoons.','我们学校因社团众多而出名,人人都渴望在社团里有个名额。米娅画画很擅长,也喜欢画卡通。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l70',2,NULL,'Her brother is proud of her, but he''s afraid of speaking in public himself. "You should be responsible for the art club," the teacher said. "You''re capable of leading it."','她哥哥为她感到自豪,可他自己却害怕当众讲话。“你应该负责美术社,”老师说,“你有能力领导它。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l70',3,NULL,'Mia was surprised at the offer and grateful to her teacher. "I''m a little worried about the work," she said, "but I''m ready for a challenge."','米娅对这个提议感到惊讶,也很感激老师。“我有点担心工作量,”她说,“不过我准备好迎接挑战了。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l70',4,NULL,'The teacher was pleased with her answer and kind to everyone who joined. Soon the club was full of students keen on art.','老师对她的回答很满意,对每个加入的人都很友善。很快,美术社就挤满了热爱艺术的学生。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l70',5,NULL,'Mia was sorry for the ones who couldn''t get in, but the room was capable of holding only twenty. By the end of the year, she was famous for the best art show the school had ever seen.','米娅为那些没能进来的人感到惋惜,但活动室只能容纳二十个人。到年底时,她因为办了全校最棒的一场画展而出了名。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
