INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l70','be good at','',NULL,'/bi ɡʊd æt/','Mia is really good at painting.','米娅画画很擅长。','He is good at solving problems.','他很擅长解决问题。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l70','be responsible for','',NULL,'/bi rɪˈspɑːnsəbl fɔːr/','She is responsible for the art club.','她负责美术社。','The captain is responsible for the whole team.','队长对整个队伍负责。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l70','be proud of','',NULL,'/bi praʊd əv/','Her brother is proud of her.','她哥哥为她感到自豪。','We are proud of our school.','我们为自己的学校感到自豪。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l70','be keen on','',NULL,'/bi kiːn ɑːn/','The students are keen on art.','学生们热衷于艺术。','She is keen on playing tennis.','她热衷于打网球。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp1','choice','{"stem":"\"Our school is famous ___ its many clubs.\"(“因…而出名”配哪个介词)","options":["to","of","for","at"],"answer_index":2,"stem_cn":"我们学校因社团众多而出名。","explanation_cn":"“因…而出名”固定用 famous for。✓ Our school is famous for its many clubs. ✗ of / at / to:都不与 famous 搭配表“因…出名”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp1','choice','{"stem":"\"Everyone is eager ___ a place in a club.\"(“渴望得到”配哪个介词)","options":["for","with","at","of"],"answer_index":0,"stem_cn":"人人都渴望在社团里有个名额。","explanation_cn":"“渴望得到…”固定用 eager for。✓ Everyone is eager for a place in a club. ✗ of / at / with:都不与 eager 搭配。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp1','choice','{"stem":"\"Mia is now responsible ___ the art club.\"(“对…负责”配哪个介词)","options":["of","to","for","at"],"answer_index":2,"stem_cn":"米娅现在负责美术社。","explanation_cn":"“对…负责”固定用 responsible for。✓ Mia is responsible for the art club. ✗ of / to / at:都不与 responsible 搭配。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp2','choice','{"stem":"\"Her brother is proud ___ her.\"(“为…自豪”配哪个介词)","options":["for","at","with","of"],"answer_index":3,"stem_cn":"她哥哥为她感到自豪。","explanation_cn":"“为…自豪”固定用 proud of。✓ Her brother is proud of her. ✗ for / at / with:都不与 proud 搭配。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp2','choice','{"stem":"\"He is afraid ___ speaking in public.\"(“害怕”配哪个介词)","options":["for","at","of","to"],"answer_index":2,"stem_cn":"他害怕当众讲话。","explanation_cn":"“害怕…”固定用 afraid of。✓ He is afraid of speaking in public. ✗ for / at / to:都不与 afraid 搭配(afraid to do 是另一结构,这里后接 -ing 要用 of)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp2','choice','{"stem":"\"Mia is capable ___ leading the club.\"(“有能力做”配哪个介词)","options":["at","for","to","of"],"answer_index":3,"stem_cn":"米娅有能力领导这个社团。","explanation_cn":"“有能力做…”固定用 capable of。✓ Mia is capable of leading the club. ✗ for / to / at:都不与 capable 搭配。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp3','choice','{"stem":"\"Mia is really good ___ painting.\"(“擅长”配哪个介词)","options":["at","of","for","in"],"answer_index":0,"stem_cn":"米娅画画很擅长。","explanation_cn":"“擅长…”固定用 good at。✓ Mia is really good at painting. ✗ in / of / for:都不与 good 搭配表“擅长”。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp3','choice','{"stem":"\"Her friend is quick ___ learning new things.\"(“在…上反应快”配哪个介词)","options":["of","in","at","to"],"answer_index":2,"stem_cn":"她朋友学新东西很快。","explanation_cn":"“在…方面反应快、动作快”用 quick at。✓ Her friend is quick at learning new things. ✗ in / of / to:都不与 quick 这样搭配。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp3','choice','{"stem":"\"Everyone was surprised ___ the news.\"(“对…感到惊讶”配哪个介词)","options":["for","with","of","at"],"answer_index":3,"stem_cn":"大家对这个消息感到惊讶。","explanation_cn":"“对…感到惊讶”固定用 surprised at。✓ Everyone was surprised at the news. ✗ of / for / with:都不与 surprised 搭配。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp4','choice','{"stem":"\"Mia was grateful ___ her teacher.\"(“感激”配哪个介词)","options":["at","for","to","of"],"answer_index":2,"stem_cn":"米娅很感激她的老师。","explanation_cn":"“感激(某人)”固定用 grateful to sb。✓ Mia was grateful to her teacher. ✗ for / of / at:grateful for 后面接“事”，接“人”要用 to。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp4','choice','{"stem":"\"The teacher is kind ___ everyone who joins.\"(“对…友善”配哪个介词)","options":["to","for","with","of"],"answer_index":0,"stem_cn":"老师对每个加入的人都很友善。","explanation_cn":"“对…友善”固定用 kind to sb。✓ The teacher is kind to everyone. ✗ for / of / with:都不与 kind 搭配。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp4','choice','{"stem":"\"The teacher was pleased ___ her answer.\"(“对…满意”配哪个介词)","options":["to","at","of","with"],"answer_index":3,"stem_cn":"老师对她的回答很满意。","explanation_cn":"“对…满意”固定用 pleased with。✓ The teacher was pleased with her answer. ✗ to / of / at:都不与 pleased 搭配。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp5','choice','{"stem":"\"Mia is a little worried ___ the work.\"(“担心”配哪个介词)","options":["at","about","of","for"],"answer_index":1,"stem_cn":"米娅有点担心工作量。","explanation_cn":"“担心…”固定用 worried about。✓ Mia is a little worried about the work. ✗ for / of / at:都不与 worried 搭配。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp5','choice','{"stem":"\"The students are keen ___ art.\"(“热衷于”配哪个介词)","options":["for","at","on","of"],"answer_index":2,"stem_cn":"学生们热衷于艺术。","explanation_cn":"“热衷于…”固定用 keen on。✓ The students are keen on art. ✗ at / of / for:都不与 keen 搭配。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp5','choice','{"stem":"\"I''m sorry ___ the mistake I made.\"(“为(某事)抱歉”配哪个介词)","options":["at","of","to","about"],"answer_index":3,"stem_cn":"我为我犯的错误感到抱歉。","explanation_cn":"“为(某事)抱歉”用 sorry about sth。✓ I''m sorry about the mistake I made. ✗ at / of / to:都不与 sorry 这样搭配(sorry for sb 是为“人”惋惜)。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp6','choice','{"stem":"be responsible for something 的意思是:","options":["对…负责","对…陌生","对…厌倦","对…好奇"],"answer_index":0,"explanation_cn":"be responsible for sth = 对某事负责、负责某事。如 She is responsible for the club 她负责这个社团。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp6','choice','{"stem":"be fond of something 的意思是:","options":["厌恶…","害怕…","擅长…","喜爱…"],"answer_index":3,"explanation_cn":"be fond of sth = 喜爱某物。如 fond of drawing 喜欢画画。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',5,'am2_l70_gp6','choice','{"stem":"be capable of doing 的意思是:","options":["拒绝做…","有能力做…","没兴趣做…","忘记做…"],"answer_index":1,"explanation_cn":"be capable of doing = 有能力做某事。如 capable of leading it 有能力领导它。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',6,NULL,'choice','{"stem":"美语里\"数学\"常说:","options":["number-class","maths","count-study","math"],"answer_index":3,"explanation_cn":"美语“数学”说 math;英式说 maths。✓ She is good at math. 她数学很好。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',6,NULL,'choice','{"stem":"美语里\"橡皮\"常说:","options":["eraser","wipe-stick","rubber","clean-block"],"answer_index":0,"explanation_cn":"美语“橡皮”说 eraser;英式说 rubber。✓ Can I borrow your eraser? 能借下你的橡皮吗?"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',6,NULL,'choice','{"stem":"eager 的意思是:","options":["害怕的","疲惫的","骄傲的","渴望的,热切的"],"answer_index":3,"explanation_cn":"eager = 渴望的、热切的。✓ eager for a place 渴望有个名额。\n顺带记:疲惫的 = tired;害怕的 = afraid;骄傲的 = proud."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',6,NULL,'choice','{"stem":"famous 的意思是:","options":["普通的","著名的","廉价的","陌生的"],"answer_index":1,"explanation_cn":"famous = 著名的。✓ famous for its clubs 因社团而出名。\n顺带记:陌生的 = strange;普通的 = ordinary;廉价的 = cheap."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',6,NULL,'choice','{"stem":"grateful 的意思是:","options":["生气的","骄傲的","失望的","感激的"],"answer_index":3,"explanation_cn":"grateful = 感激的。✓ grateful to her teacher 感激她的老师。\n顺带记:生气的 = angry;失望的 = disappointed;骄傲的 = proud."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',6,NULL,'choice','{"stem":"capable 的意思是:","options":["好奇的","无助的","有能力的","谨慎的"],"answer_index":2,"explanation_cn":"capable = 有能力的。✓ capable of leading it 有能力领导它。\n顺带记:无助的 = helpless;好奇的 = curious;谨慎的 = careful."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',7,NULL,'cloze','{"stem":"第 1 空","context":"Our school is famous ___1___ its clubs. Mia is good ___2___ painting and fond ___3___ drawing. The teacher said she was capable ___4___ leading the art club.","blank_no":1,"options":["for","of","at","to"],"answer_index":0,"explanation_cn":"“因…而出名”用 famous for。✓ Our school is famous for its clubs.\n✗ of / at / to:都不与 famous 搭配。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',7,NULL,'cloze','{"stem":"第 2 空","context":"Our school is famous ___1___ its clubs. Mia is good ___2___ painting and fond ___3___ drawing. The teacher said she was capable ___4___ leading the art club.","blank_no":2,"options":["at","in","of","for"],"answer_index":0,"explanation_cn":"“擅长…”用 good at。✓ Mia is good at painting.\n✗ in / of / for:都不与 good 搭配表“擅长”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',7,NULL,'cloze','{"stem":"第 3 空","context":"Our school is famous ___1___ its clubs. Mia is good ___2___ painting and fond ___3___ drawing. The teacher said she was capable ___4___ leading the art club.","blank_no":3,"options":["of","for","at","to"],"answer_index":0,"explanation_cn":"“喜爱…”用 fond of。✓ Mia is fond of drawing.\n✗ for / at / to:都不与 fond 搭配。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',7,NULL,'cloze','{"stem":"第 4 空","context":"Our school is famous ___1___ its clubs. Mia is good ___2___ painting and fond ___3___ drawing. The teacher said she was capable ___4___ leading the art club.","blank_no":4,"options":["of","for","to","at"],"answer_index":0,"explanation_cn":"“有能力做…”用 capable of。✓ She was capable of leading the art club.\n✗ for / to / at:都不与 capable 搭配。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',8,NULL,'choice','{"stem":"What is the school famous for?","options":["Its old bell","Its garden","Its many clubs","Its swimming pool"],"answer_index":2,"explanation_cn":"课文说 Our school is famous for its many clubs。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',8,NULL,'choice','{"stem":"What is Mia good at?","options":["Running and jumping","Painting, and she is fond of drawing cartoons","Cooking and baking","Singing and dancing"],"answer_index":1,"explanation_cn":"课文说 Mia is really good at painting and fond of drawing cartoons。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',8,NULL,'choice','{"stem":"What did the teacher ask Mia to be responsible for?","options":["The sports day","The library","The whole school","The art club"],"answer_index":3,"explanation_cn":"课文说 \"You should be responsible for the art club,\" the teacher said。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',9,NULL,'choice','{"stem":"你想说\"我们学校因社团众多而出名\"(be famous for):","options":["Our school is famous of its many clubs.","Our school is famous for its many clubs.","Our school is famous to its many clubs.","Our school is famous at its many clubs."],"answer_index":1,"explanation_cn":"“因…而出名”固定搭配 famous for。✓ Our school is famous for its many clubs. 场合:说某地/某人因某事而有名。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',9,NULL,'choice','{"stem":"你想说\"他害怕当众讲话\"(be afraid of):","options":["He is afraid at speaking in public.","He is afraid to speaking in public.","He is afraid of speaking in public.","He is afraid for speaking in public."],"answer_index":2,"explanation_cn":"“害怕做…”固定搭配 afraid of + doing。✓ He is afraid of speaking in public. 场合:说某人怕做某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',9,NULL,'choice','{"stem":"你想说\"米娅很感激她的老师\"(be grateful to):","options":["Mia was grateful to her teacher.","Mia was grateful of her teacher.","Mia was grateful for her teacher.","Mia was grateful at her teacher."],"answer_index":0,"explanation_cn":"“感激某人”固定搭配 grateful to sb。✓ Mia was grateful to her teacher. 场合:说对某人心怀感激。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',10,NULL,'choice','{"stem":"eager 的意思是:","options":["疲惫的","渴望的,热切的","骄傲的","害怕的"],"answer_index":1,"explanation_cn":"eager = 渴望的、热切的。✓ eager for a place 渴望有个名额。\n顺带记:疲惫的 = tired;害怕的 = afraid;骄傲的 = proud."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',10,NULL,'choice','{"stem":"grateful 的意思是:","options":["感激的","失望的","骄傲的","生气的"],"answer_index":0,"explanation_cn":"grateful = 感激的。✓ grateful to her teacher 感激老师。\n顺带记:生气的 = angry;失望的 = disappointed;骄傲的 = proud."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',10,NULL,'choice','{"stem":"\"Our school is famous ___ its clubs.\"(“因…而出名”配哪个介词)","options":["of","for","to","at"],"answer_index":1,"stem_cn":"我们学校因社团众多而出名。","explanation_cn":"“因…而出名”用 famous for。✓ Our school is famous for its clubs.\n✗ of / at / to:都不与 famous 搭配。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',10,NULL,'choice','{"stem":"\"He is afraid ___ speaking in public.\"(“害怕”配哪个介词)","options":["at","for","of","to"],"answer_index":2,"stem_cn":"他害怕当众讲话。","explanation_cn":"“害怕做…”用 afraid of。✓ He is afraid of speaking in public.\n✗ for / at / to:都不与 afraid 搭配接 -ing。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',10,NULL,'choice','{"stem":"\"be responsible for\" 的意思是:","options":["对…好奇","对…负责","对…满意","对…陌生"],"answer_index":1,"explanation_cn":"be responsible for = 对…负责。如 responsible for the art club 负责美术社。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',10,NULL,'choice','{"stem":"\"be good at\" 的意思是:","options":["负责…","厌倦…","擅长…","害怕…"],"answer_index":2,"explanation_cn":"be good at = 擅长…。如 good at painting 擅长画画。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',10,NULL,'choice','{"stem":"Why was Mia chosen to lead the art club?","options":["Because she was the oldest student","Because she is good at painting and the teacher thought she was capable of leading it","Because her brother asked the teacher","Because no one else wanted to"],"answer_index":1,"passage":"Our school is famous for its many clubs, and everyone is eager for a place in one. Mia is really good at painting and fond of drawing cartoons. Her brother is proud of her, but he''s afraid of speaking in public himself. \"You should be responsible for the art club,\" the teacher said. \"You''re capable of leading it.\" Mia was surprised at the offer and grateful to her teacher. \"I''m a little worried about the work,\" she said, \"but I''m ready for a challenge.\" The teacher was pleased with her answer and kind to everyone who joined. Soon the club was full of students keen on art. Mia was sorry for the ones who couldn''t get in, but the room was capable of holding only twenty. By the end of the year, she was famous for the best art show the school had ever seen.","explanation_cn":"课文说 Mia is really good at painting… \"You''re capable of leading it,\" said the teacher。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',10,NULL,'choice','{"stem":"How did Mia feel about the teacher''s offer?","options":["Angry and disappointed","Bored and tired","Surprised at it and grateful to her teacher","Afraid and unwilling"],"answer_index":2,"passage":"Our school is famous for its many clubs, and everyone is eager for a place in one. Mia is really good at painting and fond of drawing cartoons. Her brother is proud of her, but he''s afraid of speaking in public himself. \"You should be responsible for the art club,\" the teacher said. \"You''re capable of leading it.\" Mia was surprised at the offer and grateful to her teacher. \"I''m a little worried about the work,\" she said, \"but I''m ready for a challenge.\" The teacher was pleased with her answer and kind to everyone who joined. Soon the club was full of students keen on art. Mia was sorry for the ones who couldn''t get in, but the room was capable of holding only twenty. By the end of the year, she was famous for the best art show the school had ever seen.","explanation_cn":"课文说 Mia was surprised at the offer and grateful to her teacher。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',10,NULL,'choice','{"stem":"What is Mia fond of?","options":["Drawing cartoons","Baking cakes","Playing soccer","Reading novels"],"answer_index":0,"audio":"Our school is famous for its many clubs, and everyone is eager for a place in one. Mia is really good at painting and fond of drawing cartoons. Her brother is proud of her, but he''s afraid of speaking in public himself. \"You should be responsible for the art club,\" the teacher said. \"You''re capable of leading it.\" Mia was surprised at the offer and grateful to her teacher. \"I''m a little worried about the work,\" she said, \"but I''m ready for a challenge.\" The teacher was pleased with her answer and kind to everyone who joined. Soon the club was full of students keen on art. Mia was sorry for the ones who couldn''t get in, but the room was capable of holding only twenty. By the end of the year, she was famous for the best art show the school had ever seen.","explanation_cn":"课文说 Mia is… fond of drawing cartoons。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l70',10,NULL,'choice','{"stem":"How many students could the art club room hold?","options":["Only five","Only twenty","About a hundred","Fifty"],"answer_index":1,"audio":"Our school is famous for its many clubs, and everyone is eager for a place in one. Mia is really good at painting and fond of drawing cartoons. Her brother is proud of her, but he''s afraid of speaking in public himself. \"You should be responsible for the art club,\" the teacher said. \"You''re capable of leading it.\" Mia was surprised at the offer and grateful to her teacher. \"I''m a little worried about the work,\" she said, \"but I''m ready for a challenge.\" The teacher was pleased with her answer and kind to everyone who joined. Soon the club was full of students keen on art. Mia was sorry for the ones who couldn''t get in, but the room was capable of holding only twenty. By the end of the year, she was famous for the best art show the school had ever seen.","explanation_cn":"课文说 the room was capable of holding only twenty。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l71',2,9,71,'A famous clock','一个著名的大钟','Review KS60-69 综合复习(教材 L71 Key structures):与过去事实相反的虚拟条件句(had not been burned → would never have been erected)、各时态被动(can be heard / were being built / are connected)、have sth done(have the clock checked)、现在完成/过去完成进行/将来完成的复习;SD 易混词 official/employee/salesclerk(美语 clerk)、hang→hung(悬挂)','当你游览伦敦时,首先看到的东西之一就是“大本”钟,即那座从英国广播公司的广播中全世界都可以听到它声音的著名大钟。如果不是国会大厦在1834年被焚毁的话,这座大钟永远也不会建造。“大本”钟得名于本杰明·霍尔爵士,因为当建造新的国会大厦时,他负责建造大钟。此钟不仅外型巨大,而且走时也非常准确。格林尼治天文台的官员们每天两次派人矫正此钟。当大钟打点的时候,你可以从英国广播公司的广播中听到,因为钟塔上接了麦克风。“大本”钟很少出差错。然而有一次,它却把时间报错了。在钟塔上干活的一位油漆工把一只油漆桶挂在了一根指针上,把钟弄慢了!','{"q":"Listen and answer — Has Big Ben ever gone wrong?","options":["Yes, once — a painter hung a pot of paint on a hand and slowed it down","No, it has never gone wrong","Yes, it goes wrong every day","Yes, it stopped for a whole year"],"answer_index":0}'::jsonb,'{"title":"Review KS60-69 综合复习","intro":"本课复习前十课重点:①与过去事实相反的虚拟条件句——if 从句用 had (not) been done,主句用 would have (been) done(If Parliament had not been burned down, the clock would never have been erected);②各时态被动 be + 过去分词(can be heard / were being built / are connected);③have sth done 请别人做(have the clock checked);④现在完成(has gone wrong)、过去完成进行(had been working)、将来完成(will have worked)。","table":{"headers":["复习点","例子"],"rows":[["与过去相反虚拟","If it had not been burned, it would never have been erected."],["各时态被动","can be heard / were being built"],["have sth done","have the clock checked twice a day"],["现在完成","Big Ben has rarely gone wrong."],["过去完成进行","A painter had been working on the tower."]]},"specialRules":[{"rule":"SD 易混词:official=(政府/机构的)官员;employee=雇员、职工;shop assistant(店员)美语说 salesclerk / clerk。","mark":"official/employee/clerk"},{"rule":"SD hang 两套变化:表''悬挂(物品)''时 hang-hung-hung(She hung the washing);表旧时''绞死(人)''时 hang-hanged-hanged(仅认读,不作重点)。","mark":"hang/hung"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l71',1,NULL,'When you visit London, one of the first things you will see is Big Ben, the famous clock which can be heard all over the world on the B.B.C. If the Houses of Parliament had not been burned down in 1834, the great clock would never have been erected.','当你游览伦敦时,首先看到的东西之一就是“大本”钟,即那座声音能通过英国广播公司传遍全世界的著名大钟。如果不是国会大厦在1834年被焚毁的话,这座大钟永远也不会建造。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l71',2,NULL,'Big Ben takes its name from Sir Benjamin Hall, who was responsible for the making of the clock when the new Houses of Parliament were being built. It is not only of immense size, but is extremely accurate as well.','“大本”钟得名于本杰明·霍尔爵士,因为当建造新的国会大厦时,他负责建造大钟。此钟不仅外型巨大,而且走时也非常准确。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l71',3,NULL,'Officials from Greenwich Observatory have the clock checked twice a day. On the B.B.C. you can hear the clock when it is actually striking, because microphones are connected to the clock tower.','格林尼治天文台的官员们每天两次派人矫正此钟。当大钟打点的时候,你可以从英国广播公司的广播中听到,因为钟塔上接了麦克风。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l71',4,NULL,'Big Ben has rarely gone wrong. Once, however, it failed to give the correct time.','“大本”钟很少出差错。然而有一次,它却把时间报错了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l71',5,NULL,'A painter who had been working on the tower hung a pot of paint on one of the hands and slowed it down!','在钟塔上干活的一位油漆工把一只油漆桶挂在了一根指针上,把钟弄慢了!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
