INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l71','take one''s name from','',NULL,'/teɪk neɪm frɒm/','Big Ben takes its name from Sir Benjamin Hall.','大本钟得名于本杰明·霍尔爵士。','The town takes its name from the river.','这座城镇得名于那条河。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l71','be responsible for','',NULL,'/bi rɪˈspɑːnsəbl fɔːr/','He was responsible for the making of the clock.','他负责大钟的建造。','She is responsible for the whole team.','她对整个团队负责。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l71','all over the world','',NULL,'/ɔːl ˈoʊvər ðə wɜːrld/','It can be heard all over the world.','全世界都能听到它。','People know this song all over the world.','全世界的人都知道这首歌。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l71','have sth checked','',NULL,'/hæv ˈtʃekt/','They have the clock checked twice a day.','他们每天让人校对此钟两次。','Have your eyes checked once a year.','每年让人检查一次眼睛。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp1','choice','{"stem":"\"If the Houses of Parliament ___ down in 1834, the clock would never have been erected.\"(与过去相反:if 从句用 had (not) been done)","options":["would not burn","had not been burned","were not burned","had not burned"],"answer_index":1,"stem_cn":"如果国会大厦1834年没被烧毁,大钟就永远不会建起来。","explanation_cn":"与过去事实相反的假设:if 从句用 had (not) been + 过去分词(被动)。✓ If the Houses of Parliament had not been burned down… ✗ were not burned:那是与现在相反;✗ had not burned:主动,此处是\"被烧\";✗ would not burn:if 从句里不用 would。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp1','choice','{"stem":"\"If Parliament had not been burned down, the great clock ___ erected.\"(与过去相反:主句用 would have been done)","options":["had never been","will never be","would never have been","would never be"],"answer_index":2,"stem_cn":"如果国会大厦没被烧毁,大钟永远不会被建起来。","explanation_cn":"与过去事实相反:主句用 would have been + 过去分词。✓ the great clock would never have been erected. ✗ would never be:那是与现在相反;✗ will never be:真实将来;✗ had never been:主句不用 had。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp1','choice','{"stem":"\"If they had checked it earlier, the fault ___ found.\"(与过去相反:主句用完成体的虚拟被动形式)","options":["would have been","had been","would be","will be"],"answer_index":0,"stem_cn":"要是他们早点检查,故障早就被发现了。","explanation_cn":"与过去事实相反:主句用 would have been + 过去分词。✓ the fault would have been found. ✗ would be:与现在相反;✗ will be:真实将来;✗ had been:主句不用 had。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp2','choice','{"stem":"\"Big Ben is the famous clock which ___ all over the world on the B.B.C.\"(情态被动:能被听到)","options":["can hear","can be hearing","can be heard","can heard"],"answer_index":2,"stem_cn":"大本钟是那座声音能传遍全世界的著名大钟。","explanation_cn":"情态被动 = can be + 过去分词。✓ the clock which can be heard all over the world. ✗ can hear:主动;✗ can be hearing:无此形式;✗ can heard:缺 be。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp2','choice','{"stem":"\"Big Ben got its name when the new Houses of Parliament ___.\"(过去进行被动:正在建造)","options":["were being built","were building","had built","was being built"],"answer_index":0,"stem_cn":"新国会大厦正在建造时,大本钟得了名。","explanation_cn":"过去进行的被动 = were being + 过去分词。✓ when the new Houses of Parliament were being built. ✗ were building:主动;✗ was being built:主语复数不用 was;✗ had built:过去完成主动。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp2','choice','{"stem":"\"Microphones ___ to the clock tower.\"(一般现在被动:被连接)","options":["are connecting","have connect","are connected","connect"],"answer_index":2,"stem_cn":"麦克风连接在钟塔上。","explanation_cn":"一般现在的被动 = are + 过去分词。✓ microphones are connected to the clock tower. ✗ connect:主动;✗ are connecting:进行主动;✗ have connect:形式错。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp3','choice','{"stem":"\"Officials from Greenwich Observatory have the clock ___ twice a day.\"(请别人做:每天让人校对两次)","options":["check","checking","to check","checked"],"answer_index":3,"stem_cn":"格林尼治天文台的官员每天两次让人校对此钟。","explanation_cn":"\"请别人做\"用 have + 物 + 过去分词。✓ have the clock checked twice a day. ✗ check:原形不表\"被…\";✗ checking:现在分词;✗ to check:不定式不合此结构。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp3','choice','{"stem":"\"You should have your watch ___ if it keeps stopping.\"(请别人做:让人修表)","options":["repairing","repaired","to repair","repair"],"answer_index":1,"stem_cn":"表老停的话,你该拿去修。","explanation_cn":"\"请别人做\"用 have + 物 + 过去分词。✓ have your watch repaired. ✗ repair:原形;✗ repairing:现在分词;✗ to repair:不定式不合。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp4','choice','{"stem":"\"Big Ben has rarely ___ wrong.\"(现在完成:很少出过差错)","options":["gone","going","went","been going"],"answer_index":0,"stem_cn":"大本钟很少出过差错。","explanation_cn":"现在完成 = has + 过去分词;go 的过去分词是 gone。✓ Big Ben has rarely gone wrong. ✗ went:一般过去;✗ going:现在分词;✗ been going:此处不表持续。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp4','choice','{"stem":"\"A painter who ___ on the tower hung a pot of paint on one of the hands.\"(过去完成进行:一直在干活)","options":["has worked","was work","had been working","worked"],"answer_index":2,"stem_cn":"一位一直在塔上干活的油漆工把油漆桶挂在了指针上。","explanation_cn":"过去完成进行 = had been + 现在分词,强调之前一直在做。✓ A painter who had been working on the tower… ✗ worked:一般过去;✗ has worked:现在完成;✗ was work:形式错。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp4','choice','{"stem":"\"By December I ___ on this novel for ten months.\"(将来完成进行:到12月已工作了10个月)","options":["have worked","will work","worked","will have been working"],"answer_index":3,"stem_cn":"到12月,我这部小说就写了10个月了。","explanation_cn":"将来完成进行 = will have been + 现在分词,表到将来某时已持续多久。✓ By December I will have been working on it for ten months. ✗ will work:一般将来;✗ have worked:现在完成;✗ worked:一般过去。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp5','choice','{"stem":"\"___ from Greenwich Observatory check the clock.\"(天文台的''官员'')","options":["Officials","Customers","Clerks","Employees"],"answer_index":0,"stem_cn":"格林尼治天文台的官员们校对此钟。","explanation_cn":"official = (机构/政府的)官员、工作人员。✓ Officials from Greenwich Observatory. ✗ Employees:雇员(受雇于公司);✗ Clerks:职员/店员;✗ Customers:顾客。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp5','choice','{"stem":"\"Over a thousand factory ___ work here.\"(工厂的''雇员、职工'')","options":["guests","employees","officials","clerks"],"answer_index":1,"stem_cn":"一千多名工厂雇员在这儿上班。","explanation_cn":"employee = 雇员、职工(受雇于公司/工厂)。✓ Over a thousand factory employees. ✗ officials:官员;✗ clerks:职员/店员;✗ guests:客人。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp5','choice','{"stem":"\"She works as a ___ in a clothing store.\"(在服装店''当店员'';美语说法)","options":["shop assistant","official","salesclerk","employer"],"answer_index":2,"stem_cn":"她在一家服装店当店员。","explanation_cn":"美语\"(商店)店员\"说 salesclerk / clerk;英式说 shop assistant。✓ She works as a salesclerk. ✗ shop assistant:英式说法;✗ official:官员;✗ employer:雇主(是老板,不是店员)。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp6','choice','{"stem":"\"When the sun came out, she ___ the washing on the line.\"(悬挂衣物:hang 的过去式)","options":["hung","hang","hanged","hangs"],"answer_index":0,"stem_cn":"太阳出来时,她把洗好的衣服晾在绳子上。","explanation_cn":"表\"悬挂(物品)\"时,hang 的过去式是 hung。✓ She hung the washing on the line. ✗ hanged:那是旧时\"绞死(人)\"的过去式;✗ hang:未用过去式;✗ hangs:第三人称现在式。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp6','choice','{"stem":"\"He ___ a pot of paint on one of the clock''s hands.\"(把…挂上:hang 的过去式)","options":["hanged","hung","hanging","hang"],"answer_index":1,"stem_cn":"他把一桶油漆挂在了钟的一根指针上。","explanation_cn":"表\"悬挂(物品)\"用 hung。✓ He hung a pot of paint on one of the hands. ✗ hanged:用于\"绞死(人)\";✗ hang:未用过去式;✗ hanging:现在分词。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp6','choice','{"stem":"\"I ___ my coat in the hall.\"(把外套挂起来:hang 的过去式)","options":["hangs","hang","hung","hanged"],"answer_index":2,"stem_cn":"我把外套挂在门厅里。","explanation_cn":"表\"悬挂(物品)\"用 hung。✓ I hung my coat in the hall. ✗ hanged:用于\"绞死(人)\";✗ hang:未用过去式;✗ hangs:现在式。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',5,'am2_l71_gp6','choice','{"stem":"\"They ___ a big picture on the wall yesterday.\"(把画挂上:hang 的过去式)","options":["hung","hang","hanging","hanged"],"answer_index":0,"stem_cn":"昨天他们在墙上挂了一幅大画。","explanation_cn":"表\"悬挂(物品)\"用 hung。✓ They hung a big picture on the wall. ✗ hanged:用于\"绞死(人)\";✗ hang:未用过去式;✗ hanging:现在分词。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',6,NULL,'choice','{"stem":"美语里\"店员\"常说:","options":["store boy","shop assistant","shop worker","salesclerk"],"answer_index":3,"explanation_cn":"美语\"(商店)店员\"常说 salesclerk / clerk;英式说 shop assistant。✓ She is a salesclerk. 她是店员。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',6,NULL,'choice','{"stem":"美语里\"电梯\"常说:","options":["lift","up-stairs box","elevator","rising room"],"answer_index":2,"explanation_cn":"美语\"电梯\"常说 elevator;英式说 lift。✓ Take the elevator to the top floor. 坐电梯上顶楼。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',6,NULL,'choice','{"stem":"parliament 的意思是:","options":["医院","议会,国会","学校","法院"],"answer_index":1,"explanation_cn":"parliament = 议会、国会。✓ the Houses of Parliament 国会大厦。\n顺带记:法院 = court;学校 = school;医院 = hospital."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',6,NULL,'choice','{"stem":"erect 的意思是:","options":["建造,竖立","参观","拆除","修理"],"answer_index":0,"explanation_cn":"erect = 建造、竖立。✓ the clock would never have been erected 大钟永远不会被建起。\n顺带记:拆除 = pull down;修理 = repair;参观 = visit."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',6,NULL,'choice','{"stem":"accurate 的意思是:","options":["古老的","准确的","模糊的","昂贵的"],"answer_index":1,"explanation_cn":"accurate = 准确的。✓ extremely accurate 非常准确。\n顺带记:模糊的 = vague;昂贵的 = expensive;古老的 = ancient."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',6,NULL,'choice','{"stem":"immense 的意思是:","options":["破旧的","微小的","普通的","巨大的"],"answer_index":3,"explanation_cn":"immense = 巨大的。✓ of immense size 外型巨大。\n顺带记:微小的 = tiny;普通的 = ordinary;破旧的 = shabby."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',7,NULL,'cloze','{"stem":"第 1 空","context":"If the Houses of Parliament ___1___ down in 1834, the great clock would never have been erected. Big Ben got its name when the new Houses of Parliament ___2___. Officials have the clock ___3___ twice a day. Big Ben has rarely ___4___ wrong.","blank_no":1,"options":["had not been burned","were not burned","had not burned","would not burn"],"answer_index":0,"explanation_cn":"与过去相反:if 从句用 had (not) been + 过去分词。✓ If the Houses of Parliament had not been burned down…\n✗ were not burned:与现在相反;✗ had not burned:主动;✗ would not burn:if 从句不用 would。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',7,NULL,'cloze','{"stem":"第 2 空","context":"If the Houses of Parliament ___1___ down in 1834, the great clock would never have been erected. Big Ben got its name when the new Houses of Parliament ___2___. Officials have the clock ___3___ twice a day. Big Ben has rarely ___4___ wrong.","blank_no":2,"options":["were being built","were building","was being built","had built"],"answer_index":0,"explanation_cn":"过去进行的被动 = were being + 过去分词。✓ when the new Houses of Parliament were being built.\n✗ were building:主动;✗ was being built:主语复数不用 was;✗ had built:过去完成主动。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',7,NULL,'cloze','{"stem":"第 3 空","context":"If the Houses of Parliament ___1___ down in 1834, the great clock would never have been erected. Big Ben got its name when the new Houses of Parliament ___2___. Officials have the clock ___3___ twice a day. Big Ben has rarely ___4___ wrong.","blank_no":3,"options":["checked","check","checking","to check"],"answer_index":0,"explanation_cn":"\"请别人做\"用 have + 物 + 过去分词。✓ have the clock checked twice a day.\n✗ check:原形;✗ checking:现在分词;✗ to check:不定式不合。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',7,NULL,'cloze','{"stem":"第 4 空","context":"If the Houses of Parliament ___1___ down in 1834, the great clock would never have been erected. Big Ben got its name when the new Houses of Parliament ___2___. Officials have the clock ___3___ twice a day. Big Ben has rarely ___4___ wrong.","blank_no":4,"options":["gone","went","going","been going"],"answer_index":0,"explanation_cn":"现在完成 = has + 过去分词(gone)。✓ Big Ben has rarely gone wrong.\n✗ went:一般过去;✗ going:现在分词;✗ been going:此处不表持续。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',8,NULL,'choice','{"stem":"What is Big Ben?","options":["The famous London clock that can be heard all over the world on the B.B.C.","A radio station","A history museum","A tall office building"],"answer_index":0,"explanation_cn":"课文说 Big Ben, the famous clock which can be heard all over the world on the B.B.C。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',8,NULL,'choice','{"stem":"Why would the great clock never have been built?","options":["If London had not grown so large","If the Houses of Parliament had not been burned down in 1834","If Sir Benjamin Hall had not been born","If radio had never been invented"],"answer_index":1,"explanation_cn":"课文说 If the Houses of Parliament had not been burned down in 1834, the great clock would never have been erected。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',8,NULL,'choice','{"stem":"How is Big Ben kept so accurate?","options":["A computer runs it","It is never touched at all","Officials from Greenwich Observatory have the clock checked twice a day","It checks itself automatically"],"answer_index":2,"explanation_cn":"课文说 Officials from Greenwich Observatory have the clock checked twice a day,所以它非常准确。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',9,NULL,'choice','{"stem":"你想说\"如果国会大厦没被烧毁,大钟就永远不会被建起来\"(与过去相反虚拟,被动):","options":["If Parliament had not been burned down, the clock will never have been erected.","If Parliament had not been burned down, the clock would never have been erected.","If Parliament had not been burned down, the clock had never been erected.","If Parliament had not been burned down, the clock would never be erected."],"answer_index":1,"explanation_cn":"与过去相反:if 从句 had (not) been done,主句 would have been done。✓ …the clock would never have been erected. 场合:回想过去、设想相反的结果。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',9,NULL,'choice','{"stem":"你想说\"官员们每天让人把钟校对两次\"(have sth done):","options":["The officials have the clock checked twice a day.","The officials have checking the clock twice a day.","The officials have the clock check twice a day.","The officials have the clock to check twice a day."],"answer_index":0,"explanation_cn":"\"请别人做\"用 have + 物 + 过去分词。✓ The officials have the clock checked twice a day. 场合:说让别人替自己做某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',9,NULL,'choice','{"stem":"你想说\"太阳出来时,她把洗好的衣服晾了起来\"(悬挂,hang 的过去式):","options":["When the sun came out, she hang the washing on the line.","When the sun came out, she hanged the washing on the line.","When the sun came out, she hangs the washing on the line.","When the sun came out, she hung the washing on the line."],"answer_index":3,"explanation_cn":"表\"悬挂(物品)\"用 hung。✓ she hung the washing on the line. 场合:说把衣物等挂起来。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',10,NULL,'choice','{"stem":"parliament 的意思是:","options":["法院","学校","议会,国会","医院"],"answer_index":2,"explanation_cn":"parliament = 议会、国会。✓ the Houses of Parliament 国会大厦。\n顺带记:法院 = court;学校 = school;医院 = hospital."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',10,NULL,'choice','{"stem":"accurate 的意思是:","options":["模糊的","昂贵的","古老的","准确的"],"answer_index":3,"explanation_cn":"accurate = 准确的。✓ extremely accurate 非常准确。\n顺带记:模糊的 = vague;昂贵的 = expensive;古老的 = ancient."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',10,NULL,'choice','{"stem":"\"Big Ben got its name when the new Houses of Parliament ___.\"(过去进行被动)","options":["had built","were building","were being built","was being built"],"answer_index":2,"stem_cn":"新国会大厦正在建造时,大本钟得了名。","explanation_cn":"过去进行的被动 = were being + 过去分词。✓ when the new Houses of Parliament were being built.\n✗ were building:主动;✗ was being built:数不合;✗ had built:过去完成主动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',10,NULL,'choice','{"stem":"\"Officials have the clock ___ twice a day.\"(have sth done 请别人做)","options":["checking","checked","to check","check"],"answer_index":1,"stem_cn":"官员们每天让人把钟校对两次。","explanation_cn":"\"请别人做\"用 have + 物 + 过去分词。✓ have the clock checked twice a day.\n✗ check:原形;✗ checking:现在分词;✗ to check:不定式不合。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',10,NULL,'choice','{"stem":"\"have + 物 + 过去分词\" 表示的意思是:","options":["自己亲手做某事","将要亲自去做","请/让别人做某事","已经做完某事"],"answer_index":2,"explanation_cn":"have + 物 + 过去分词表示请/让别人做某事(自己不亲自做),如 have the clock checked=让人校对钟。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',10,NULL,'choice','{"stem":"hang 表示\"悬挂(物品)\"时,它的过去式是:","options":["hanged","hung","hanging","hangs"],"answer_index":1,"explanation_cn":"hang 表示\"悬挂(物品)\"时,过去式和过去分词都是 hung(hang-hung-hung)。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',10,NULL,'choice','{"stem":"Why has Big Ben rarely gone wrong?","options":["It is very small and simple","It is never actually used","It is checked twice a day and is extremely accurate despite its size","It runs on batteries"],"answer_index":2,"passage":"When you visit London, one of the first things you will see is Big Ben, the famous clock which can be heard all over the world on the B.B.C. If the Houses of Parliament had not been burned down in 1834, the great clock would never have been erected. Big Ben takes its name from Sir Benjamin Hall, who was responsible for the making of the clock when the new Houses of Parliament were being built. It is not only of immense size, but is extremely accurate as well. Officials from Greenwich Observatory have the clock checked twice a day. On the B.B.C. you can hear the clock when it is actually striking, because microphones are connected to the clock tower. Big Ben has rarely gone wrong. Once, however, it failed to give the correct time. A painter who had been working on the tower hung a pot of paint on one of the hands and slowed it down!","explanation_cn":"课文说 It is not only of immense size, but is extremely accurate as well… have the clock checked twice a day。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',10,NULL,'choice','{"stem":"What happened the one time Big Ben failed to give the correct time?","options":["A painter hung a pot of paint on one of the hands and slowed it down","The power went out","Someone stole one of the hands","It was struck by lightning"],"answer_index":0,"passage":"When you visit London, one of the first things you will see is Big Ben, the famous clock which can be heard all over the world on the B.B.C. If the Houses of Parliament had not been burned down in 1834, the great clock would never have been erected. Big Ben takes its name from Sir Benjamin Hall, who was responsible for the making of the clock when the new Houses of Parliament were being built. It is not only of immense size, but is extremely accurate as well. Officials from Greenwich Observatory have the clock checked twice a day. On the B.B.C. you can hear the clock when it is actually striking, because microphones are connected to the clock tower. Big Ben has rarely gone wrong. Once, however, it failed to give the correct time. A painter who had been working on the tower hung a pot of paint on one of the hands and slowed it down!","explanation_cn":"课文说 A painter who had been working on the tower hung a pot of paint on one of the hands and slowed it down。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',10,NULL,'choice','{"stem":"Where can you hear Big Ben striking?","options":["Only inside Parliament","On television only","Nowhere anymore","On the B.B.C., because microphones are connected to the clock tower"],"answer_index":3,"audio":"When you visit London, one of the first things you will see is Big Ben, the famous clock which can be heard all over the world on the B.B.C. If the Houses of Parliament had not been burned down in 1834, the great clock would never have been erected. Big Ben takes its name from Sir Benjamin Hall, who was responsible for the making of the clock when the new Houses of Parliament were being built. It is not only of immense size, but is extremely accurate as well. Officials from Greenwich Observatory have the clock checked twice a day. On the B.B.C. you can hear the clock when it is actually striking, because microphones are connected to the clock tower. Big Ben has rarely gone wrong. Once, however, it failed to give the correct time. A painter who had been working on the tower hung a pot of paint on one of the hands and slowed it down!","explanation_cn":"课文说 On the B.B.C. you can hear the clock when it is actually striking, because microphones are connected to the clock tower。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l71',10,NULL,'choice','{"stem":"Has Big Ben ever gone wrong?","options":["Yes, every single day","No, never","Yes, once, when a painter slowed it down","Yes, it stopped for a whole year"],"answer_index":2,"audio":"When you visit London, one of the first things you will see is Big Ben, the famous clock which can be heard all over the world on the B.B.C. If the Houses of Parliament had not been burned down in 1834, the great clock would never have been erected. Big Ben takes its name from Sir Benjamin Hall, who was responsible for the making of the clock when the new Houses of Parliament were being built. It is not only of immense size, but is extremely accurate as well. Officials from Greenwich Observatory have the clock checked twice a day. On the B.B.C. you can hear the clock when it is actually striking, because microphones are connected to the clock tower. Big Ben has rarely gone wrong. Once, however, it failed to give the correct time. A painter who had been working on the tower hung a pot of paint on one of the hands and slowed it down!","explanation_cn":"课文说 Big Ben has rarely gone wrong. Once, however, it failed… a painter… slowed it down。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l72',2,9,72,'A car called Bluebird','“蓝鸟”汽车','Review SD50-71 复习难点(教材 L72 Special difficulties):经常容易混淆的词——lose/miss、expect/wait、raise/rise、lie/lay、beat/win、value/cost/price、accept/agree、say/tell、dress up、hung(悬挂)、hard/hardly、near/nearly;辅以课文语法过去完成被动(had been specially built / a mistake had been made)与现在完成(have reached)','杰出的赛车手马尔科姆·坎贝尔爵士是第一个以每小时超过300英里的速度驾车的人。他于1935年9月在犹他州的邦纳维尔盐滩创造了一项新的世界纪录。他驾驶的“蓝鸟”牌汽车是专门为他制造的。车身长30多英尺,装有一台2500马力的发动机。尽管坎贝尔达到了每小时超过304英里的速度,但因为开始那圈爆了一只轮胎,他很难控制住汽车。比赛结束后,坎贝尔失望地得知他的平均时速是299英里。然而几天之后,有人告诉他弄错了,他的平均时速实际是301英里。从那以后,赛车手已达到每小时600多英里的速度。很多年后,马尔科姆爵士的儿子唐纳德踏着父亲的足迹,也创造了一项世界纪录。同父亲一样,他驾驶的也是一辆叫“蓝鸟”的汽车。','{"q":"Listen and answer — What mistake was made?","options":["His average speed was first declared 299 mph, but it was really 301 mph","His car was too heavy to drive","He started the race on the wrong day","He drove the wrong car"],"answer_index":0}'::jsonb,'{"title":"Review SD50-71 易混词复习","intro":"本课复习前面若干课的“经常容易混淆的词”:①lose(丢失)vs miss(错过、没赶上);②expect(预计会…)vs wait(等待);③raise(抬高、举起,后面接宾语)vs rise(升起,自己升);④lie(躺,lying)vs lay(放置,laying);⑤beat sb(击败某人)vs win(赢得比赛/奖);⑥value(看重)/cost(花费多少钱)/price(定价、价格);⑦accept(接受)vs agree(同意);⑧say sth(说某话)vs tell sb(告诉某人);⑨dress up(装扮成);⑩hang→hung(悬挂物品);⑪hard(努力地)vs hardly(几乎不);⑫near(靠近)vs nearly(几乎)。另配课文语法:过去完成被动 had been done、现在完成 have done。","table":{"headers":["易混词","怎么选"],"rows":[["miss / lose","miss=错过没赶上(miss the train);lose=丢失(lose your keys)"],["expect / wait","expect=预计会…(expecting a letter);wait=在等(waiting for a bus)"],["raise / rise","raise=抬高、举起后接宾语;rise=自己升起不接宾语"],["cost / price / value","cost=花费多少钱;price=价格、定价;value=看重"],["hard / hardly","hard=努力地(work hard);hardly=几乎不(hardly ever)"]]},"specialRules":[{"rule":"美语里“练习”名词动词都拼 practice(英式动词才拼 practise);本课只教 practice 一种拼法。","mark":"practice"},{"rule":"hang 两套变化:表“悬挂(物品)”hang-hung-hung(She hung the washing);旧时“绞死(人)”才用 hanged(仅认读,不作重点)。","mark":"hang/hung"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l72',1,NULL,'The great racing driver, Sir Malcolm Campbell, was the first man to drive at over 300 miles per hour. He set up a new world record in September 1935 at Bonneville Salt Flats, Utah.','杰出的赛车手马尔科姆·坎贝尔爵士是第一个以每小时超过300英里的速度驾车的人。他于1935年9月在犹他州的邦纳维尔盐滩创造了一项新的世界纪录。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l72',2,NULL,'Bluebird, the car he was driving, had been specially built for him. It was over 30 feet in length and had a 2,500-horsepower engine.','他驾驶的“蓝鸟”牌汽车是专门为他制造的。车身长30多英尺,装有一台2500马力的发动机。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l72',3,NULL,'Although Campbell reached a speed of over 304 miles per hour, he had great difficulty in controlling the car because a tire burst during the first run.','尽管坎贝尔达到了每小时超过304英里的速度,但因为开始那圈爆了一只轮胎,他很难控制住汽车。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l72',4,NULL,'After his attempt, Campbell was disappointed to learn that his average speed had been 299 miles per hour. However, a few days later, he was told that a mistake had been made. His average speed had been 301 miles per hour.','比赛结束后,坎贝尔失望地得知他的平均时速是299英里。然而几天之后,有人告诉他弄错了,他的平均时速实际是301英里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l72',5,NULL,'Since that time, racing drivers have reached speeds over 600 miles an hour. Following in his father''s footsteps many years later, Sir Malcolm''s son, Donald, also set up a world record. Like his father, he was driving a car called Bluebird.','从那以后,赛车手已达到每小时600多英里的速度。很多年后,马尔科姆爵士的儿子唐纳德踏着父亲的足迹,也创造了一项世界纪录。同父亲一样,他驾驶的也是一辆叫“蓝鸟”的汽车。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
