INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l72','set up a record','',NULL,'/set ʌp ə ˈrekərd/','He set up a new world record in 1935.','他在1935年创造了一项新的世界纪录。','The young swimmer set up a national record.','这名年轻游泳选手创造了一项全国纪录。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l72','have great difficulty in doing','',NULL,'/hæv ɡreɪt ˈdɪfɪkəlti ɪn/','He had great difficulty in controlling the car.','他很难控制住那辆车。','I had great difficulty in finding the address.','我费了好大劲才找到那个地址。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l72','follow in one''s footsteps','',NULL,'/ˈfɑːloʊ ɪn ˈfʊtsteps/','He followed in his father''s footsteps.','他踏着父亲的足迹(继承父业)。','She followed in her mother''s footsteps and became a doctor.','她效仿母亲,也当了医生。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l72','be disappointed to learn','',NULL,'/bi ˌdɪsəˈpɔɪntɪd tə lɜːrn/','Campbell was disappointed to learn that his speed had been 299 mph.','坎贝尔失望地得知他的时速是299英里。','We were disappointed to learn that the show was cancelled.','我们失望地得知演出取消了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp1','choice','{"stem":"\"Hurry up or you will ___ the train.\"(错过、没赶上用哪个词)","options":["loose","miss","drop","lose"],"answer_index":1,"stem_cn":"快点,不然你会错过这趟火车。","explanation_cn":"错过、赶不上某班车/船/机用 miss。✓ Hurry up or you will miss the train. ✗ lose:那是\"丢失(东西)\";✗ loose:是形容词\"松的\";✗ drop:是\"掉落\"。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp1','choice','{"stem":"\"I''m ___ to receive a letter from her soon.\"(预计不久会收到)","options":["hoped","waiting for","expecting","waiting"],"answer_index":2,"stem_cn":"我预计不久会收到她的一封信。","explanation_cn":"预计、料想会收到/发生某事用 expect。✓ I''m expecting to receive a letter soon. ✗ waiting:只表\"在等\",不含\"预计会来\"这层;✗ waiting for:后面接人/物,不接不定式;✗ hoped:时态不合,且语气也不对。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp1','choice','{"stem":"\"Be careful not to ___ your keys again.\"(丢失用哪个词)","options":["drop off","lose","miss","loose"],"answer_index":1,"stem_cn":"小心别再把钥匙弄丢了。","explanation_cn":"丢失、失去某物用 lose。✓ Be careful not to lose your keys again. ✗ miss:是\"错过、没赶上\";✗ loose:是形容词\"松的\";✗ drop off:是\"顺路放下、送到\"。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp2','choice','{"stem":"\"You should ___ that picture a few inches.\"(把画往上抬高,后面接宾语)","options":["arise","raise up high","rise","raise"],"answer_index":3,"stem_cn":"你应该把那幅画往上抬高几英寸。","explanation_cn":"把某物往上抬高、举起,后面要带一个被抬的东西,用 raise。✓ You should raise that picture a few inches. ✗ rise:是\"(自己)升起、上升\",后面不带被抬的东西;✗ arise:是\"(问题等)出现\";✗ raise up high:啰嗦重复。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp2','choice','{"stem":"\"I love ___ in bed on Sunday morning.\"(躺着用哪个形)","options":["laid","lieing","lying","laying"],"answer_index":2,"stem_cn":"我喜欢周日早晨躺在床上。","explanation_cn":"\"躺着\"是 lie,它的 -ing 形式是 lying。✓ I love lying in bed on Sunday morning. ✗ laying:那是 lay(放置)的 -ing;✗ lieing:拼写错误;✗ laid:是 lay 的过去式。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp2','choice','{"stem":"\"He always ___ me at chess.\"(击败某人用哪个词)","options":["beats","earns","wins","gains"],"answer_index":0,"stem_cn":"下国际象棋他总是赢我。","explanation_cn":"\"下棋/比赛中击败某人\"用 beat sb。✓ He always beats me at chess. ✗ wins:win 后面接比赛/奖项(win the game),不直接接人;✗ gains:是\"获得(利益)\";✗ earns:是\"挣得\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp3','choice','{"stem":"\"Whenever I buy anything new, my father asks me the ___.\"(问多少钱、价格)","options":["worth","value","price","cost"],"answer_index":2,"stem_cn":"每次我买新东西,爸爸都问我价格。","explanation_cn":"\"价格、要多少钱\"这个名词用 price。✓ my father asks me the price. ✗ cost:多作动词\"花费\";✗ value:是\"价值、看重\";✗ worth:通常作介词/形容词,不这样单用作名词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp3','choice','{"stem":"\"That house ___ a fortune to build.\"(花费了一大笔钱用哪个词)","options":["spent","priced","valued","cost"],"answer_index":3,"stem_cn":"那栋房子造起来花了一大笔钱。","explanation_cn":"\"某物花费(多少钱)\"用动词 cost。✓ That house cost a fortune to build. ✗ valued:是\"给…估价/看重\";✗ priced:是\"给…定价\";✗ spent:花钱的是人不是房子(people spend money)。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp3','choice','{"stem":"\"I ___ your advice a great deal.\"(非常看重、重视)","options":["price","cost","value","pay"],"answer_index":2,"stem_cn":"我非常看重你的建议。","explanation_cn":"\"看重、重视\"用 value。✓ I value your advice a great deal. ✗ cost:是\"花费(钱)\";✗ price:是\"定价\";✗ pay:是\"付款\"。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp4','choice','{"stem":"\"I could not ___ his offer.\"(接受提议用哪个词)","options":["accept","receive to","agree","admit"],"answer_index":0,"stem_cn":"我无法接受他的提议。","explanation_cn":"\"接受(邀请、提议、礼物)\"用 accept。✓ I could not accept his offer. ✗ agree:是\"同意(某看法/做某事)\",接 with/to;✗ admit:是\"承认\";✗ receive to:搭配错误。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp4','choice','{"stem":"\"I can ___ no more. He told me a secret.\"(说某话用哪个词)","options":["speak","tell","say","talk"],"answer_index":2,"stem_cn":"我不能再多说了,他告诉了我一个秘密。","explanation_cn":"\"说某句话/某内容\"用 say(后面直接接说的话)。✓ I can say no more. ✗ tell:后面要先接\"告诉的人\"(tell me);✗ speak:是\"讲话、说某种语言\";✗ talk:是\"交谈\"。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp4','choice','{"stem":"\"Who is going to ___ as Santa Claus this year?\"(装扮成…用哪个词组)","options":["wear","put on","dress","dress up"],"answer_index":3,"stem_cn":"今年谁来装扮成圣诞老人?","explanation_cn":"\"打扮成、装扮成\"用 dress up (as)。✓ Who is going to dress up as Santa Claus? ✗ dress:只是\"给…穿衣\";✗ wear:是\"穿着(某件衣服)\";✗ put on:是\"穿上(动作)\"。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp5','choice','{"stem":"\"When the sun came out, she ___ the washing on the line.\"(把衣物挂起来:hang 的过去式)","options":["hangs","hung","hang","hanged"],"answer_index":1,"stem_cn":"太阳出来时,她把洗好的衣服晾在绳子上。","explanation_cn":"表\"把衣物等悬挂起来\"时,hang 的过去式是 hung。✓ She hung the washing on the line. ✗ hanged:那是旧时\"绞死(人)\"的过去式;✗ hang:没用过去式;✗ hangs:第三人称现在式。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp5','choice','{"stem":"\"He has been working too ___ lately.\"(努力地用哪个词)","options":["hard","hardly","hardness","harder"],"answer_index":0,"stem_cn":"他最近一直工作得太拼命了。","explanation_cn":"\"努力地、拼命地\"用 hard(它本身就是副词)。✓ He has been working too hard. ✗ hardly:意思相反,是\"几乎不\";✗ hardness:是名词;✗ harder:是比较级,此处不合。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp5','choice','{"stem":"\"He was ___ run over by a car.\"(差点、几乎用哪个词)","options":["nearer","near","nearly","nearby"],"answer_index":2,"stem_cn":"他差点被一辆车撞了。","explanation_cn":"\"差点、几乎\"用 nearly。✓ He was nearly run over by a car. ✗ near:是\"靠近(某处)\";✗ nearby:是\"附近的\";✗ nearer:是比较级\"更近\"。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp6','choice','{"stem":"\"Bluebird, the car he was driving, ___ specially built for him.\"(专门为他制造:过去完成被动)","options":["has been","had been","had","was being"],"answer_index":1,"stem_cn":"他驾驶的蓝鸟车是专门为他制造的。","explanation_cn":"过去某时\"更早以前就已经被做好\"用过去完成被动 = had been + 过去分词。✓ Bluebird had been specially built for him. ✗ was being:那是\"当时正在被造\";✗ has been:是现在完成,时间点不对;✗ had:缺 been,构不成被动。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp6','choice','{"stem":"\"A few days later, he was told that a mistake ___ made.\"(出了个差错:过去完成被动)","options":["had been","was being","has been","had"],"answer_index":0,"stem_cn":"几天后,有人告诉他弄错了。","explanation_cn":"\"(更早)已经出了个差错\"用过去完成被动 = had been + 过去分词。✓ a mistake had been made. ✗ was being:那是\"当时正被犯\";✗ has been:现在完成,时间不对;✗ had:缺 been。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',5,'am2_l72_gp6','choice','{"stem":"\"Since that time, racing drivers ___ speeds over 600 miles an hour.\"(至今已达到:现在完成)","options":["reached","have reached","are reaching","had reached"],"answer_index":1,"stem_cn":"从那时起,赛车手已达到每小时600多英里的速度。","explanation_cn":"\"从那时起至今已经达到\"用现在完成 = have + 过去分词。✓ racing drivers have reached speeds over 600 mph. ✗ reached:一般过去,不含\"持续到现在\";✗ had reached:过去完成,时间点不对;✗ are reaching:现在进行,不表\"已达到\"。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',6,NULL,'choice','{"stem":"美语里\"汽车后备箱\"常说:","options":["rear-case","trunk","boot","back-box"],"answer_index":1,"explanation_cn":"美语\"汽车后备箱\"说 trunk;英式说 boot。✓ Put the bags in the trunk. 把包放进后备箱。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',6,NULL,'choice','{"stem":"美语里\"发动机罩(引擎盖)\"常说:","options":["motor-cover","engine-lid","hood","bonnet"],"answer_index":2,"explanation_cn":"美语\"发动机罩、引擎盖\"说 hood;英式说 bonnet。✓ Open the hood to check the engine. 打开引擎盖检查发动机。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',6,NULL,'choice','{"stem":"burst 的意思是:","options":["加速","爆裂","修理","关闭"],"answer_index":1,"explanation_cn":"burst = 爆裂、胀破。✓ a tire burst during the first run 开始那圈爆了一只轮胎。\n顺带记:关闭 = close;加速 = speed up;修理 = repair."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',6,NULL,'choice','{"stem":"average 的意思是:","options":["最高的","缓慢的","平均的","危险的"],"answer_index":2,"explanation_cn":"average = 平均的。✓ his average speed 他的平均速度。\n顺带记:最高的 = highest;危险的 = dangerous;缓慢的 = slow."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',6,NULL,'choice','{"stem":"horsepower 的意思是:","options":["马力","里程","油耗","车速"],"answer_index":0,"explanation_cn":"horsepower = 马力(发动机功率单位)。✓ a 2,500-horsepower engine 一台2500马力的发动机。\n顺带记:车速 = speed;里程 = mileage;油耗 = fuel use."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',6,NULL,'choice','{"stem":"footstep 的意思是:","options":["楼梯","足迹,脚步","门槛","车轮"],"answer_index":1,"explanation_cn":"footstep = 足迹、脚步。✓ following in his father''s footsteps 踏着父亲的足迹。\n顺带记:楼梯 = stairs;门槛 = doorstep;车轮 = wheel."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',7,NULL,'cloze','{"stem":"第 1 空","context":"Bluebird ___1___ specially built for Campbell. Although he reached over 304 mph, a tire ___2___ during the first run. He was disappointed to ___3___ that his average was only 299 mph, but a few days later a mistake ___4___ been made — it was really 301.","blank_no":1,"options":["had been","was being","has been","had"],"answer_index":0,"explanation_cn":"过去完成被动 = had been + 过去分词。✓ Bluebird had been specially built for Campbell.\n✗ was being:当时正在被造;✗ has been:现在完成时间不对;✗ had:缺 been。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',7,NULL,'cloze','{"stem":"第 2 空","context":"Bluebird ___1___ specially built for Campbell. Although he reached over 304 mph, a tire ___2___ during the first run. He was disappointed to ___3___ that his average was only 299 mph, but a few days later a mistake ___4___ been made — it was really 301.","blank_no":2,"options":["burst","bursted","was burst","bursting"],"answer_index":0,"explanation_cn":"burst 三态同形(burst-burst-burst),此处一般过去。✓ a tire burst during the first run.\n✗ bursted:无此形式;✗ was burst:多余;✗ bursting:缺助动词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',7,NULL,'cloze','{"stem":"第 3 空","context":"Bluebird ___1___ specially built for Campbell. Although he reached over 304 mph, a tire ___2___ during the first run. He was disappointed to ___3___ that his average was only 299 mph, but a few days later a mistake ___4___ been made — it was really 301.","blank_no":3,"options":["learn","teach","study","read"],"answer_index":0,"explanation_cn":"\"得知、了解到\"用 learn。✓ He was disappointed to learn that his average was only 299 mph.\n✗ teach:是\"教\";✗ study:是\"钻研学习\";✗ read:是\"阅读\"。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',7,NULL,'cloze','{"stem":"第 4 空","context":"Bluebird ___1___ specially built for Campbell. Although he reached over 304 mph, a tire ___2___ during the first run. He was disappointed to ___3___ that his average was only 299 mph, but a few days later a mistake ___4___ been made — it was really 301.","blank_no":4,"options":["had","was","has","would"],"answer_index":0,"explanation_cn":"\"a mistake ___ been made\"要用 had 构成过去完成被动(had been made)。✓ a mistake had been made.\n✗ was:配 been 不成过去完成;✗ has:时间点不对;✗ would:语气不合。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',8,NULL,'choice','{"stem":"What was Sir Malcolm Campbell the first man to do?","options":["Win a chess match","Build a museum of cars","Fly across the ocean","Drive at over 300 miles per hour"],"answer_index":3,"explanation_cn":"课文说 Sir Malcolm Campbell was the first man to drive at over 300 miles per hour。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',8,NULL,'choice','{"stem":"Why did he have great difficulty controlling the car?","options":["Because it began to rain","Because a tire burst during the first run","Because the road was blocked","Because the engine was too small"],"answer_index":1,"explanation_cn":"课文说 he had great difficulty in controlling the car because a tire burst during the first run。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',8,NULL,'choice','{"stem":"What was his real average speed?","options":["600 miles per hour","250 miles per hour","301 miles per hour, after a mistake had been corrected","299 miles per hour exactly"],"answer_index":2,"explanation_cn":"课文说 he was told that a mistake had been made. His average speed had been 301 miles per hour。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',9,NULL,'choice','{"stem":"你想说\"他驾驶的车是专门为他制造的\"(过去完成被动):","options":["The car he was driving had been specially built for him.","The car he was driving has specially built for him.","The car he was driving was specially building for him.","The car he was driving had specially built for him."],"answer_index":0,"explanation_cn":"过去完成被动 = had been + 过去分词。✓ The car he was driving had been specially built for him. 场合:说某物在更早以前就已被专门做好。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',9,NULL,'choice','{"stem":"你想说\"快点,不然你会错过火车\"(错过没赶上,不是丢失):","options":["Hurry up or you will drop the train.","Hurry up or you will lose the train.","Hurry up or you will miss the train.","Hurry up or you will loose the train."],"answer_index":2,"explanation_cn":"\"错过、赶不上\"用 miss,不用 lose。✓ Hurry up or you will miss the train. 场合:提醒别人快点、别误车。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',9,NULL,'choice','{"stem":"你想说\"他踏着父亲的足迹,也创造了纪录\"(固定说法):","options":["Following on his father''s footsteps, he also set up a record.","Following in his father''s foot, he also set up a record.","Following after his father''s step, he also set up a record.","Following in his father''s footsteps, he also set up a record."],"answer_index":3,"explanation_cn":"\"踏着某人的足迹\"固定说 follow in one''s footsteps(介词是 in、名词用复数 footsteps)。✓ Following in his father''s footsteps, he also set up a record. 场合:说某人效仿前辈、继承事业。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',10,NULL,'choice','{"stem":"burst 的意思是:","options":["关闭","修理","加速","爆裂"],"answer_index":3,"explanation_cn":"burst = 爆裂、胀破。✓ a tire burst 一只轮胎爆了。\n顺带记:关闭 = close;加速 = speed up;修理 = repair."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',10,NULL,'choice','{"stem":"footstep 的意思是:","options":["足迹,脚步","楼梯","门槛","车轮"],"answer_index":0,"explanation_cn":"footstep = 足迹、脚步。✓ in his father''s footsteps 踏着父亲的足迹。\n顺带记:楼梯 = stairs;门槛 = doorstep;车轮 = wheel."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',10,NULL,'choice','{"stem":"\"The car he was driving ___ specially built for him.\"(过去完成被动)","options":["had","was being","has been","had been"],"answer_index":3,"stem_cn":"他驾驶的车是专门为他制造的。","explanation_cn":"过去完成被动 = had been + 过去分词。✓ The car had been specially built for him.\n✗ was being:当时正在被造;✗ has been:现在完成时间不对;✗ had:缺 been。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',10,NULL,'choice','{"stem":"\"A few days later, he was told that a mistake ___ made.\"(过去完成被动)","options":["was being","has been","had been","had"],"answer_index":2,"stem_cn":"几天后,有人告诉他弄错了。","explanation_cn":"过去完成被动 = had been + 过去分词。✓ a mistake had been made.\n✗ was being:当时正被犯;✗ has been:时间点不对;✗ had:缺 been。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',10,NULL,'choice','{"stem":"\"miss the train\" 里 miss 的意思是:","options":["丢失","躲避","击中","错过、没赶上"],"answer_index":3,"explanation_cn":"miss the train = 错过、没赶上火车。miss 和 lose 不同:lose 是\"丢失(东西)\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',10,NULL,'choice','{"stem":"\"follow in one''s footsteps\" 的意思是:","options":["数某人的脚印","效仿某人、走同样的路","踩到某人的脚","跟在某人后面散步"],"answer_index":1,"explanation_cn":"follow in one''s footsteps = 效仿某人、继承前人事业、走同样的路。介词用 in,footsteps 用复数。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',10,NULL,'choice','{"stem":"One of these statements is true. Which one?","options":["There was some doubt whether Sir Malcolm had maintained an average speed of 301 miles per hour","Sir Malcolm''s car had a 250-horsepower engine","Sir Malcolm set up a world record recently","Sir Malcolm''s average speed was 299 miles per hour"],"answer_index":0,"passage":"The great racing driver, Sir Malcolm Campbell, was the first man to drive at over 300 miles per hour. He set up a new world record in September 1935 at Bonneville Salt Flats, Utah. Bluebird, the car he was driving, had been specially built for him. It was over 30 feet in length and had a 2,500-horsepower engine. Although Campbell reached a speed of over 304 miles per hour, he had great difficulty in controlling the car because a tire burst during the first run. After his attempt, Campbell was disappointed to learn that his average speed had been 299 miles per hour. However, a few days later, he was told that a mistake had been made. His average speed had been 301 miles per hour. Since that time, racing drivers have reached speeds over 600 miles an hour. Following in his father''s footsteps many years later, Sir Malcolm''s son, Donald, also set up a world record. Like his father, he was driving a car called Bluebird.","explanation_cn":"课文说他的平均时速先被宣布为299,后来才更正为301——所以对\"是否达到301\"一度是有疑问的。其余三项都与课文不符。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',10,NULL,'choice','{"stem":"Whose footsteps did Donald follow in, and what was his car called?","options":["Nobody''s; he never raced","His father Sir Malcolm''s; his car was also called Bluebird","A stranger''s; his car was called Redbird","His brother''s; his car had no name"],"answer_index":1,"passage":"The great racing driver, Sir Malcolm Campbell, was the first man to drive at over 300 miles per hour. He set up a new world record in September 1935 at Bonneville Salt Flats, Utah. Bluebird, the car he was driving, had been specially built for him. It was over 30 feet in length and had a 2,500-horsepower engine. Although Campbell reached a speed of over 304 miles per hour, he had great difficulty in controlling the car because a tire burst during the first run. After his attempt, Campbell was disappointed to learn that his average speed had been 299 miles per hour. However, a few days later, he was told that a mistake had been made. His average speed had been 301 miles per hour. Since that time, racing drivers have reached speeds over 600 miles an hour. Following in his father''s footsteps many years later, Sir Malcolm''s son, Donald, also set up a world record. Like his father, he was driving a car called Bluebird.","explanation_cn":"课文说 Following in his father''s footsteps… Sir Malcolm''s son, Donald… Like his father, he was driving a car called Bluebird。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',10,NULL,'choice','{"stem":"What burst during the first run?","options":["A fuel tank","The engine","A window","A tire"],"answer_index":3,"audio":"The great racing driver, Sir Malcolm Campbell, was the first man to drive at over 300 miles per hour. He set up a new world record in September 1935 at Bonneville Salt Flats, Utah. Bluebird, the car he was driving, had been specially built for him. It was over 30 feet in length and had a 2,500-horsepower engine. Although Campbell reached a speed of over 304 miles per hour, he had great difficulty in controlling the car because a tire burst during the first run. After his attempt, Campbell was disappointed to learn that his average speed had been 299 miles per hour. However, a few days later, he was told that a mistake had been made. His average speed had been 301 miles per hour. Since that time, racing drivers have reached speeds over 600 miles an hour. Following in his father''s footsteps many years later, Sir Malcolm''s son, Donald, also set up a world record. Like his father, he was driving a car called Bluebird.","explanation_cn":"课文说 a tire burst during the first run,所以他很难控制汽车。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l72',10,NULL,'choice','{"stem":"How fast did Campbell actually average?","options":["304 miles per hour","600 miles per hour","301 miles per hour","299 miles per hour"],"answer_index":2,"audio":"The great racing driver, Sir Malcolm Campbell, was the first man to drive at over 300 miles per hour. He set up a new world record in September 1935 at Bonneville Salt Flats, Utah. Bluebird, the car he was driving, had been specially built for him. It was over 30 feet in length and had a 2,500-horsepower engine. Although Campbell reached a speed of over 304 miles per hour, he had great difficulty in controlling the car because a tire burst during the first run. After his attempt, Campbell was disappointed to learn that his average speed had been 299 miles per hour. However, a few days later, he was told that a mistake had been made. His average speed had been 301 miles per hour. Since that time, racing drivers have reached speeds over 600 miles an hour. Following in his father''s footsteps many years later, Sir Malcolm''s son, Donald, also set up a world record. Like his father, he was driving a car called Bluebird.","explanation_cn":"课文说 a mistake had been made. His average speed had been 301 miles per hour。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
